/** One partial's level from a drawn spectrum: the table read at `x` (0..1), linearly. */
function spectrumLevel(table, x) {
  if (!table || table.length === 0) return 1;
  const n = table.length;
  const pos = Math.min(1, Math.max(0, x)) * (n - 1);
  const i = Math.floor(pos);
  const a = table[i];
  const b = table[Math.min(n - 1, i + 1)];
  return a + (b - a) * (pos - i);
}

/**
 * Every partial's ratio to the note, its level before the note's own pitch is taken into account,
 * and what Damp multiplies that level by each sample - from the controls. Shared by the synth and
 * by the picture of it (figures.mjs), so the bars drawn are the levels played.
 */
function shapePartials({ partials, tilt, odd, stretch, damp, table }, sampleRate, ratioOut, baseOut, dampOut) {
  const count = Math.min(ADDITIVE_PARTIALS, Math.max(1, partials));
  const balance = Math.min(1, Math.max(-1, odd));
  const fall = Math.max(0, damp);
  const oddLevel = Math.min(1, 1 + balance);
  const evenLevel = Math.min(1, 1 - balance);
  for (let k = 0; k < ADDITIVE_PARTIALS; k++) {
    const n = k + 1;
    const ratio = Math.pow(n, 1 + stretch);
    ratioOut[k] = ratio;
    const count01 = Math.min(1, Math.max(0, count - k));
    const slope = Math.pow(10, (tilt * Math.log2(ratio)) / 20);
    const parity = n % 2 === 1 ? oddLevel : evenLevel;
    baseOut[k] = count01 * slope * parity * spectrumLevel(table, k / (ADDITIVE_PARTIALS - 1));
    dampOut[k] = Math.exp(-(ADD_DAMP_RATE * fall * (ratio - 1)) / sampleRate);
  }
}

/** How far a partial at `hz` is let through: one below the fade, none at Nyquist and above. */
function nyquistFade(hz, sampleRate) {
  return Math.min(1, Math.max(0, (0.5 * sampleRate - hz) / (ADD_NYQUIST_FADE * sampleRate)));
}

/**
 * Where each partial's level is going on a note at `hz`: faded near Nyquist, into `out`. Returns
 * what brings them to one loudness (unit summed power), which `out` is not yet multiplied by.
 */
function aimPartials(base, ratio, hz, sampleRate, out) {
  let power = 0;
  for (let k = 0; k < ADDITIVE_PARTIALS; k++) {
    const g = base[k] * nyquistFade(ratio[k] * hz, sampleRate);
    out[k] = g;
    power += g * g;
  }
  return power > ADD_SILENT_POWER ? 1 / Math.sqrt(power) : 0;
}

/** A control's value at the end of the block: a number, or the last of a block of values. */
const endOf = (v) => (typeof v === 'number' ? v : v[v.length - 1]);

/** What every voice reads, worked out once a block from the controls. */
class AdditiveParams {
  constructor() {
    this.values = Object.fromEntries(ADDITIVE.params.map((p) => [p.id, p.default]));
    // Per partial: its ratio to the note, its level before the voice's own pitch is taken into
    // account, and what Damp multiplies its level by each sample.
    this.ratio = new Float64Array(ADDITIVE_PARTIALS);
    this.base = new Float64Array(ADDITIVE_PARTIALS);
    this.dampMul = new Float64Array(ADDITIVE_PARTIALS);
    // The controls shapePartials reads, kept here so a block does not build an object for them.
    this.settings = { partials: 16, tilt: -6, odd: 0, stretch: 0, damp: 0, table: null };
    this.block = 128;
    this.attack = 0.005; this.decay = 0.1; this.sustain = 0.8; this.release = 0.15;
    this.acurve = -4; this.dcurve = -4; this.rcurve = -4;
    this.glide = 0;
    this.level = 0.7;
    this.levelA = null;
    this.bend = 0;
    this.bendRatio = new Float64Array(128);
    this.bendRatioA = null;
    this.bendEnd = 1;
  }
}

class AdditiveVoice {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    const n = ADDITIVE_PARTIALS;
    this.phase = new Float64Array(n);
    this.gain = new Float64Array(n);   // each partial's level where the ramp stands
    this.gainTo = new Float64Array(n); // and where it is going by the end of the block
    this.gainStep = new Float64Array(n);
    this.inc = new Float64Array(n);    // each partial's phase step, likewise
    this.incStep = new Float64Array(n);
    this.damp = new Float64Array(n);   // how far Damp has brought each partial down this note
    this.env = new Adsr(sampleRate);
    this.note = -1;
    this.velocity = 1;
    this.age = 0;
    this.releasing = false;
    this.holds = 0;
    this.fresh = false;
    this.targetHz = 440;
    this.currentHz = 440;
  }

  get active() { return this.env.active; }

  noteOn(note, velocity, p, seed, glideFrom) {
    this.note = note;
    this.velocity = velocity;
    this.releasing = false;
    this.targetHz = midiToHz(note);
    this.currentHz = glideFrom != null && p.glide > 0 ? glideFrom : this.targetHz;
    for (let k = 0; k < ADDITIVE_PARTIALS; k++) {
      this.phase[k] = hashPhase(seed, k);
      this.damp[k] = 1;
    }
    // The first block of a note starts every partial where it should be, rather than ramping in
    // from the note before: the envelope is what brings a note in.
    this.fresh = true;
    this.env.gateOn(true);
  }

  noteOff() {
    this.releasing = true;
    this.env.gateOff();
  }

  /** Renders a piece of the block, `offset` samples into it, adding into the outputs. */
  process(outL, outR, count, offset, p) {
    if (!this.env.active) return;
    const sr = this.sampleRate;
    if (p.glide > 0 && this.currentHz !== this.targetHz) {
      const k = 1 - Math.exp(-(count / sr) / Math.max(1e-4, p.glide));
      this.currentHz += (this.targetHz - this.currentHz) * k;
      if (Math.abs(this.currentHz - this.targetHz) < 0.01) this.currentHz = this.targetHz;
    } else {
      this.currentHz = this.targetHz;
    }
    // A still bend moves the note; a moving one rides the phase steps per sample.
    const hz = p.bendRatioA === null && p.bend ? this.currentHz * Math.pow(2, p.bend / 12) : this.currentHz;
    const heard = hz * p.bendEnd;

    // Where each partial is going: its level brought to one loudness with the others, and out
    // altogether as it nears Nyquist.
    const gainTo = this.gainTo;
    const norm = aimPartials(p.base, p.ratio, heard, sr, gainTo);
    const remaining = p.block - offset;
    const gain = this.gain;
    const gainStep = this.gainStep;
    const inc = this.inc;
    const incStep = this.incStep;
    let top = 0;
    for (let k = 0; k < ADDITIVE_PARTIALS; k++) {
      const to = gainTo[k] * norm;
      gainTo[k] = to;
      const incTo = (p.ratio[k] * hz) / sr;
      if (this.fresh) {
        gain[k] = to;
        inc[k] = incTo;
        gainStep[k] = 0;
        incStep[k] = 0;
      } else {
        gainStep[k] = (to - gain[k]) / remaining;
        incStep[k] = (incTo - inc[k]) / remaining;
      }
      if (to > 0 || gain[k] > 0) top = k + 1;
    }
    this.fresh = false;

    this.env.setStages(p.attack, p.decay, p.sustain, p.release, p.acurve, p.dcurve, p.rcurve);
    const phase = this.phase;
    const damp = this.damp;
    const dampMul = p.dampMul;
    const bendA = p.bendRatioA;
    const levelA = p.levelA;
    const vel = this.velocity * ADD_VOICE_GAIN;
    for (let i = 0; i < count; i++) {
      const t = offset + i;
      const bent = bendA === null ? 1 : bendA[t];
      let sum = 0;
      for (let k = 0; k < top; k++) {
        const d = damp[k];
        const a = (gain[k] + gainStep[k] * i) * d;
        damp[k] = d * dampMul[k];
        let ph = phase[k];
        const x = ph * ADD_SINE_SIZE;
        const j = x | 0;
        const s = ADD_SINE[j];
        sum += (s + (ADD_SINE[j + 1] - s) * (x - j)) * a;
        ph += (inc[k] + incStep[k] * i) * bent;
        if (ph >= 1) ph -= Math.floor(ph);
        phase[k] = ph;
      }
      const g = this.env.next() * vel * (levelA === null ? p.level : levelA[t]);
      outL[i] += sum * g;
      outR[i] += sum * g;
    }
    // Where the ramps have got to - exactly where they were aimed, at the end of the block.
    const end = offset + count >= p.block;
    for (let k = 0; k < ADDITIVE_PARTIALS; k++) {
      gain[k] = end ? gainTo[k] : gain[k] + gainStep[k] * count;
      inc[k] = end ? (p.ratio[k] * hz) / sr : inc[k] + incStep[k] * count;
    }
  }
}

class AdditiveSynth {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.params = new AdditiveParams();
    this.voices = Array.from({ length: 16 }, () => new AdditiveVoice(sampleRate)); // as the Wavetable's
    this.voiceCount = 8;
    this.clock = 0;
    this.seed = 1;
    this.events = [];
    this.tables = [];  // option index -> a drawn spectrum, sampled by the engine
  }

  /** The controls in real units: a number, or a block of values for one a signal is moving. */
  setParams(values) {
    const s = this.params.values;
    for (const p of ADDITIVE.params) {
      const v = values[p.id];
      if (v === undefined) continue;
      if (typeof v === 'number' ? Number.isFinite(v) : v.length > 0) s[p.id] = v;
    }
    const count = endOf(s.voices);
    if (Number.isFinite(count)) this.voiceCount = Math.max(1, Math.round(count));
    // The voices are made as the count asks for them - there is no most - so a count past what is
    // made grows the list, once, at the new high mark.
    while (this.voices.length < this.voiceCount) this.voices.push(new AdditiveVoice(this.sampleRate));
  }

  /** Keeps a drawn spectrum in a Spectrum slot. */
  loadShape(paramId, index, table) {
    if (paramId !== 'spectrum' || !table?.length) return false;
    this.tables[Math.max(0, Math.round(index))] = table;
    return true;
  }

  /**
   * The track's .bend(), in semitones: a number while it is still, a block of values while
   * something moves it (see bendOf in worklets/shared.mjs).
   */
  setBend(bend) {
    const p = this.params;
    if (typeof bend === 'number') {
      p.bend = Number.isFinite(bend) ? bend : 0;
      p.bendRatioA = null;
      return;
    }
    if (p.bendRatio.length < bend.length) p.bendRatio = new Float64Array(bend.length);
    for (let i = 0; i < bend.length; i++) p.bendRatio[i] = Math.pow(2, bend[i] / 12);
    p.bend = bend[0];
    p.bendRatioA = p.bendRatio;
  }

  queueNoteOn(note, velocity, offset = 0) { this.events.push({ at: Math.max(0, offset | 0), kind: 1, note, velocity }); }
  queueNoteOff(note, offset = 0) { this.events.push({ at: Math.max(0, offset | 0), kind: 0, note, velocity: 0 }); }

  allNotesOff() {
    this.events.length = 0;
    for (const v of this.voices) {
      v.holds = 0;
      if (v.active) v.noteOff();
    }
  }

  get activeVoices() {
    let n = 0;
    for (const v of this.voices) if (v.active) n++;
    return n;
  }

  /** The voice already on this note, a free one, the oldest releasing one, or the oldest. */
  allocate(note) {
    let free = null;
    let oldestReleasing = null;
    let oldest = null;
    for (let i = 0; i < this.voiceCount; i++) {
      const v = this.voices[i];
      if (v.active && v.note === note && !v.releasing) return v;
      if (!v.active) { if (!free) free = v; continue; }
      if (v.releasing && (!oldestReleasing || v.age < oldestReleasing.age)) oldestReleasing = v;
      if (!oldest || v.age < oldest.age) oldest = v;
    }
    return free ?? oldestReleasing ?? oldest ?? this.voices[0];
  }

  startNote(note, velocity) {
    const voice = this.allocate(note);
    // Glide slides from whatever this voice was last playing.
    const from = voice.active && voice.note >= 0 ? midiToHz(voice.note) : null;
    const holds = voice.active && voice.note === note && !voice.releasing ? voice.holds + 1 : 1;
    voice.age = this.clock++;
    this.seed = (this.seed * 1664525 + 1013904223) >>> 0;
    voice.noteOn(note, velocity, this.params, this.seed, from);
    voice.holds = holds;
  }

  stopNote(note) {
    for (const v of this.voices) {
      if (!(v.active && v.note === note && !v.releasing)) continue;
      if (--v.holds > 0) continue; // an earlier note on this pitch ending: a later one still holds it
      v.holds = 0;
      v.noteOff();
    }
  }

  /** The block's partials - ratios, levels, damping - from the controls where the block ends. */
  _prepare(count) {
    const p = this.params;
    const s = p.values;
    const sr = this.sampleRate;
    p.block = count;
    const slot = Math.round(endOf(s.spectrum));
    const set = p.settings;
    set.partials = endOf(s.partials);
    set.tilt = endOf(s.tilt);
    set.odd = endOf(s.odd);
    set.stretch = endOf(s.stretch);
    set.damp = endOf(s.damp);
    set.table = slot >= 1 ? (this.tables[slot] ?? null) : null;
    shapePartials(set, sr, p.ratio, p.base, p.dampMul);
    p.attack = endOf(s['ampenv.attack']);
    p.decay = endOf(s['ampenv.decay']);
    p.sustain = endOf(s['ampenv.sustain']);
    p.release = endOf(s['ampenv.release']);
    p.acurve = endOf(s['env.acurve']);
    p.dcurve = endOf(s['env.dcurve']);
    p.rcurve = endOf(s['env.rcurve']);
    p.glide = endOf(s.glide);
    const level = s.level;
    if (typeof level === 'number') { p.level = level; p.levelA = null; } else { p.level = level[0]; p.levelA = level.length > 1 ? level : null; }
    p.bendEnd = p.bendRatioA === null ? 1 : p.bendRatioA[count - 1];
  }

  /** Renders one block, split wherever a queued note edge falls. */
  process(outL, outR, count) {
    this._prepare(count);
    const events = this.events;
    if (events.length > 1) events.sort((a, b) => a.at - b.at);
    let at = 0;
    let next = 0;
    while (at < count) {
      while (next < events.length && events[next].at <= at) {
        const e = events[next++];
        if (e.kind === 1) this.startNote(e.note, e.velocity); else this.stopNote(e.note);
      }
      const until = next < events.length ? Math.min(count, events[next].at) : count;
      const n = until - at;
      if (n > 0) {
        const l = at === 0 && n === outL.length ? outL : outL.subarray(at, at + n);
        const r = at === 0 && n === outR.length ? outR : outR.subarray(at, at + n);
        for (const v of this.voices) if (v.active) v.process(l, r, n, at, this.params);
      }
      at = until;
    }
    if (next >= events.length) events.length = 0;
    else this.events = events.slice(next).map((e) => ({ ...e, at: Math.max(0, e.at - count) }));
  }
}

// ---- src/dsp/blep.mjs --------------------------------------------
// Band-limited steps, for any signal whose edges are jumps at known times.
//
// A square wave, a sample-and-hold, a pulse: all of them are flat stretches joined by jumps, and a
// jump drawn straight onto the sample grid has energy at every frequency, which folds back below
// half the sample rate as tones that are not in the sound. The fix is to draw each jump as a
// band-limited step - the integral of a windowed sinc - at its exact fractional time. Done as a
// correction: the plain jump goes in as it is, and the difference between it and the band-limited
// one (the residual) is added either side of it.
//
// The kernel is BLEP_HALF samples either side of the jump, so the output runs BLEP_HALF samples
// late: a jump is only known when the sample after it is reached, and its correction reaches back
// that far. The kernel cuts at half the sample rate with a Kaiser window, so the passband is flat
// to about 20 kHz at 48 kHz and what lies past 28 kHz, which is all that could fold back below
// 20 kHz, is about 80 dB down.
//
// A corner - a jump in a signal's SLOPE rather than its value, as a triangle has at its peaks - is
// drawn the same way one integral further on: the band-limited step's running integral against
// the plain ramp (`kink`). It shares the step's line, so one signal can have both.
//
// The same windowed sinc reads a signal BETWEEN its samples (HistoryLine), which is what a
// sample-and-hold clocked off the sample grid needs: what it takes has to be the signal at its own
// tick, not the nearest sample, or the tick's timing error is noise of its own.
//
// Translated line for line in osc-engine/native/devices/own/dsp/blep.h.

/** Samples either side of a jump that its correction reaches. The output is this late. */
const BLEP_HALF = 16;
/** Table points per sample, read with linear interpolation. */
const BLEP_PHASES = 128;
/** The Kaiser window's shape: about 80 dB of stopband. */
const BLEP_BETA = 7.86;

/** The zeroth-order modified Bessel function, by its series. */
function besselI0(x) {
  let sum = 1;
  let term = 1;
  const q = (x * x) / 4;
  for (let k = 1; k < 32; k++) {
    term *= q / (k * k);
    sum += term;
  }
  return sum;
}

/**
 * The windowed sinc, and the band-limited unit step that is its running integral, from BLEP_HALF
 * samples before the jump to BLEP_HALF after, at BLEP_PHASES points a sample. Built once. The
 * plain step is taken off the step as it is read, by which side of the jump a sample is on -
 * interpolating across the jump itself would smear it.
 */
function buildTables() {
  const n = 2 * BLEP_HALF * BLEP_PHASES;
  const kernel = new Float64Array(n + 1);
  const i0 = besselI0(BLEP_BETA);
  for (let i = 0; i <= n; i++) {
    const x = i / BLEP_PHASES - BLEP_HALF;
    const r = x / BLEP_HALF;
    const w = besselI0(BLEP_BETA * Math.sqrt(Math.max(0, 1 - r * r))) / i0;
    const sinc = x === 0 ? 1 : Math.sin(Math.PI * x) / (Math.PI * x);
    kernel[i] = sinc * w;
  }
  // By trapezoids, scaled to end at exactly one.
  const step = new Float64Array(n + 1);
  for (let i = 1; i <= n; i++) step[i] = step[i - 1] + (kernel[i - 1] + kernel[i]) * 0.5;
  const total = step[n];
  for (let i = 0; i <= n; i++) step[i] /= total;
  // The band-limited ramp less the plain one, max(0, x), in samples: the step's integral by
  // trapezoids, with the plain ramp taken off exactly at each point.
  const ramp = new Float64Array(n + 1);
  let area = 0;
  for (let i = 1; i <= n; i++) {
    area += (step[i - 1] + step[i]) * (0.5 / BLEP_PHASES);
    const x = i / BLEP_PHASES - BLEP_HALF;
    ramp[i] = area - (x > 0 ? x : 0);
  }
  return { kernel, step, ramp };
}

let TABLES = null;

/** The shared tables, built the first time anything asks for them. */
function tables() {
  if (TABLES === null) TABLES = buildTables();
  return TABLES;
}

/** The latest a jump can be placed before the sample it is pushed with. */
const BLEP_LAST = 1 - 1e-9;

/** Ring length: a power of two with room for the correction either side of the newest sample. */
const BLEP_RING = 64;
const BLEP_MASK = BLEP_RING - 1;

/**
 * A signal's band-limited output, BLEP_HALF samples late.
 *
 * Each sample, `jump(ago, height)` for every jump since the last sample - `ago` is how long
 * before this sample it happened, in samples, 0 <= ago < 1 - and then `push(value)` with the
 * plain signal's value at this sample, which returns the output for BLEP_HALF samples ago.
 */
class BlepLine {
  constructor() {
    this.table = tables().step;
    this.rampTable = tables().ramp;
    this.ring = new Float64Array(BLEP_RING);
    this.n = 0;
  }

  reset() {
    this.ring.fill(0);
    this.n = 0;
  }

  /** A jump of `height`, `ago` samples before the sample about to be pushed. */
  jump(ago, height) {
    const table = this.table;
    const ring = this.ring;
    // A phase that lands on an edge to the last bit can put it a whole sample back, which is the
    // end of the last sample rather than the start of this one: kept just inside.
    if (!(ago < BLEP_LAST)) ago = BLEP_LAST;
    else if (!(ago > 0)) ago = 0;
    // Sample n + k is k + ago after the jump, and the table starts BLEP_HALF before it. From
    // k = 0 on, the sample is past the jump, so the plain step is there to take off.
    for (let k = -BLEP_HALF; k < BLEP_HALF; k++) {
      const x = (k + ago + BLEP_HALF) * BLEP_PHASES;
      const i = Math.floor(x);
      const a = table[i];
      const step = a + (table[i + 1] - a) * (x - i);
      ring[(this.n + k) & BLEP_MASK] += height * (k >= 0 ? step - 1 : step);
    }
  }

  /**
   * A corner: the slope changes by `change` (in value per sample), `ago` samples before the
   * sample about to be pushed.
   */
  kink(ago, change) {
    const table = this.rampTable;
    const ring = this.ring;
    if (!(ago < BLEP_LAST)) ago = BLEP_LAST;
    else if (!(ago > 0)) ago = 0;
    for (let k = -BLEP_HALF; k < BLEP_HALF; k++) {
      const x = (k + ago + BLEP_HALF) * BLEP_PHASES;
      const i = Math.floor(x);
      const a = table[i];
      ring[(this.n + k) & BLEP_MASK] += change * (a + (table[i + 1] - a) * (x - i));
    }
  }

  /** The plain signal at this sample in; the band-limited one, BLEP_HALF samples ago, out. */
  push(value) {
    const ring = this.ring;
    ring[this.n & BLEP_MASK] += value;
    const at = (this.n - BLEP_HALF) & BLEP_MASK;
    const out = ring[at];
    ring[at] = 0;
    this.n += 1;
    return out;
  }
}

/**
 * A signal's recent past, read between its samples. `push(x)` each sample; `read(ago)` is the
 * signal BLEP_HALF + ago samples before the newest one (0 <= ago < 1), band-limited by the same
 * windowed sinc, and `at(BLEP_HALF)` the sample exactly that far back.
 */
class HistoryLine {
  constructor() {
    this.kernel = tables().kernel;
    this.ring = new Float64Array(BLEP_RING);
    this.n = 0;
  }

  reset() {
    this.ring.fill(0);
    this.n = 0;
  }

  push(x) {
    this.ring[this.n & BLEP_MASK] = x;
    this.n += 1;
  }

  /** The sample `delay` whole samples before the newest. */
  at(delay) {
    return this.ring[(this.n - 1 - delay) & BLEP_MASK];
  }

  read(ago) {
    const kernel = this.kernel;
    const ring = this.ring;
    const newest = this.n - 1;
    let sum = 0;
    let weight = 0;
    // Sample newest - BLEP_HALF + k is -(ago + k) from the time being read.
    for (let k = -BLEP_HALF; k < BLEP_HALF; k++) {
      const x = (BLEP_HALF - ago - k) * BLEP_PHASES;
      const i = Math.floor(x);
      const a = kernel[i];
      const h = a + (kernel[i + 1 <= 2 * BLEP_HALF * BLEP_PHASES ? i + 1 : i] - a) * (x - i);
      sum += ring[(newest - BLEP_HALF + k) & BLEP_MASK] * h;
      weight += h;
    }
    return sum / weight;
  }
}

// ---- src/dsp/analog.mjs ------------------------------------------
// Circuit-modeled filters: the classic analog lowpass and multimode circuits, each with the
// nonlinearity that gives it its sound.
//
// Every model is written as the circuit's own differential equations - one per capacitor - with
// each transistor pair, diode pair or amplifier stage as a saturating curve, and discretized as a
// zero-delay-feedback (topology-preserving) filter: trapezoidal integrators with the feedback
// loop solved in the same sample rather than one sample late, so the corner and the resonance
// land where the analog circuit puts them at any cutoff. The curves are handled by linearizing
// each one around where its input was a sample ago (its slope as a gain, tanh(x)/x) and solving
// the resulting linear system exactly - the "cheap" nonlinear zero-delay-feedback method from the
// virtual-analog literature, which keeps a single solve per sample and stays stable at any
// setting. Everything runs at twice the sample rate through a polyphase IIR half-band pair, which
// is what keeps a driven model's harmonics from folding back, and what makes the one-sample-old
// linearization close to the real solution.
//
// The four structures, and which models are built on each:
//   cascade   - four one-poles in a row inside a negative feedback loop: `ladder` (a transistor
//               ladder, a curve on every stage's input and output) and `ota` (transconductance
//               amplifier stages, one curve on each stage's difference, with the input partly
//               compensated so the bass survives the resonance).
//   diode     - four capacitors coupled to their neighbors through diode pairs, the top one half
//               the size of the rest: `diode`. The coupling spreads the poles, which is the
//               rubbery resonance, the slope near the corner of about 18 dB an octave, and a peak
//               that moves with the resonance.
//   sallenKey - a two-pole with positive feedback round an amplifier: `sallen` (plain resistors,
//               a diode clipper in the feedback that makes it scream) and `diodepair` (diode pairs
//               as the resistors, the input fed in at three points to pick the response).
//   stateVar  - two integrators and a damping path: `statevar` (soft amplifiers, never quite
//               oscillates), `cmos` (lopsided inverter-like amplifiers that grind) and `polar`
//               (integrators that run out of slew, hard and unstable at the top).
//
// API, one instance per channel:
//   const f = new AnalogFilter(sampleRate, ANALOG_MODELS.indexOf('diode'));
//   f.setCutoff(hz); f.setResonance(0..1); f.setDrive(1..8); f.setMorph(0..1);
//   const y = f.process(x);
// Each setter is cheap enough to call every sample (setCutoff is one tangent), and process is
// one sample in, one out. `follow(other)` copies another instance's tuning for the second
// channel of a pair; `transfer(hz)` is the small-signal response, for drawing.

/** The models, in the order a song does not depend on (the device stores the name). */
const ANALOG_MODELS = Object.freeze(['ladder', 'diode', 'sallen', 'statevar', 'cmos', 'ota', 'polar', 'diodepair']);

/** The models that take the morph control: the two-pole multimodes. */
const ANALOG_MORPHING = Object.freeze(['sallen', 'statevar', 'cmos', 'polar', 'diodepair']);

const ANALOG_STRUCTURE = Object.freeze({
  ladder: 'cascade', ota: 'cascade', diode: 'diode',
  sallen: 'sallenKey', diodepair: 'sallenKey',
  statevar: 'stateVar', cmos: 'stateVar', polar: 'stateVar',
});

// Each structure's states, as an index the inner loop switches on.
const ANALOG_CASCADE = 0;
const ANALOG_DIODE = 1;
const ANALOG_SALLEN_KEY = 2;
const ANALOG_STATE_VAR = 3;
const ANALOG_STRUCTURE_INDEX = Object.freeze({ cascade: ANALOG_CASCADE, diode: ANALOG_DIODE, sallenKey: ANALOG_SALLEN_KEY, stateVar: ANALOG_STATE_VAR });

/**
 * Per model: where the loop starts to oscillate on its own (in the structure's own feedback
 * units), the feedback at the top of the knob, and the signal level that counts as full scale
 * inside the circuit - a smaller one saturates sooner.
 *
 * `onset` is the linear threshold: 4 for a four-pole cascade (each pole turns 45 degrees at the
 * corner), 3 for a unity-gain Sallen-Key with equal parts, about 17 for the diode ladder with
 * its half-size top capacitor (found numerically from the same equations), and 2 for a
 * state-variable, whose resonance is fed back against a fixed damping of 2. A `top` under the
 * onset is a circuit that rings but never sings on its own.
 *
 * `oversample` is the rate each runs at, in multiples of the sample rate: four for the models
 * whose curves are hard enough to fold audibly at two (measured with a driven tone above the
 * cutoff, where the folded products are left standing as everything real is filtered off).
 */
const ANALOG_SPECS = Object.freeze({
  ladder:   { onset: 4, top: 4.4, headroom: 1.2, oversample: 2 },
  ota:      { onset: 4, top: 4.4, headroom: 1.8, oversample: 4 },
  diode:    { onset: 16.977, top: 16.6, headroom: 1.0, oversample: 4 },
  sallen:   { onset: 3, top: 3.3, headroom: 1.4, oversample: 2 },
  diodepair:  { onset: 3, top: 3.35, headroom: 1.0, oversample: 2 },
  statevar: { onset: 2, top: 1.94, headroom: 1.5, oversample: 2 },
  cmos:     { onset: 2, top: 2.1, headroom: 0.7, oversample: 4 },
  polar:    { onset: 2, top: 2.2, headroom: 0.5, oversample: 4 },
});

/**
 * The diode ladder's own resonant frequency in units of its stage corner: with the top
 * capacitor at half size, the loop turns 180 degrees at 1.4132 times the corner of one stage.
 * The stages are tuned that much lower, so the peak sits on the cutoff the control says.
 */
const ANALOG_DIODE_TUNE = 1.4132;

/** How much of the bass the OTA cascade's input puts back, as a share of the feedback. */
const ANALOG_OTA_COMPENSATION = 0.5;

/** How much of the bass the diode ladder's input puts back. Some, not all: the loss is the sound. */
const ANALOG_DIODE_COMPENSATION = 0.25;

/** The coupling highpass in the diode ladder's feedback, in Hz: the resonance thins at the bottom. */
const ANALOG_DIODE_FEEDBACK_HZ = 40;

/** The Sallen-Key's feedback clipper: how hard it bites (larger clips sooner). */
const ANALOG_SALLEN_CLIP = 2;

/** The diode-pair two-pole's feedback amplifier, which runs out of room sooner than its diodes. */
const ANALOG_DIODEPAIR_CLIP = 2.5;

/**
 * How much sooner the resonance path of the two self-oscillating state-variables saturates than
 * their integrators: it holds the ring to a level where the integrators are still nearly linear,
 * so a singing filter stays near the pitch the cutoff says.
 */
const ANALOG_RING_KNEE = 2.5;

/** The lopsided amplifier of the CMOS model: its curve is centered this far off zero. */
const ANALOG_CMOS_BIAS = 0.35;

/** How much sooner the polar model's integrators run out of slew than a soft amplifier. */
const ANALOG_POLAR_KNEE = 1.5;

/** The output amplifier's swing, in internal units (where 1 is a full-scale input at unity drive). */
const ANALOG_RAIL = 5;

/** Highest cutoff any model is tuned to, as a share of the (base) sample rate. */
const ANALOG_MAX_CUTOFF = 0.45;
const ANALOG_MIN_CUTOFF_HZ = 20;

/** The output DC blocker of the CMOS model, which puts an offset on its signal by its shape. */
const ANALOG_DC_HZ = 8;

/** States smaller than this are flushed to zero, so a decaying tail never goes subnormal. */
const ANALOG_FLUSH = 1e-20;

/**
 * The saturating curve every model is built from: a rational approximation of tanh that reaches
 * exactly one at three and stays there, smooth through the knee. Rational rather than a library
 * tanh so the two engines compute the same number.
 */
function analogClip(x) {
  if (x <= -3) return -1;
  if (x >= 3) return 1;
  const x2 = x * x;
  return (x * (27 + x2)) / (27 + 9 * x2);
}

/** analogClip(x) / x: the curve's secant slope, which is the gain the linearized solve uses. */
function analogClipGain(x) {
  const ax = x < 0 ? -x : x;
  if (ax >= 3) return 1 / ax;
  const x2 = x * x;
  return (27 + x2) / (27 + 9 * x2);
}

/** analogClip's slope at x. */
function analogClipSlope(x) {
  if (x <= -3 || x >= 3) return 0;
  const x2 = x * x;
  const d = 27 + 9 * x2;
  return (9 * (9 - x2) * (9 - x2)) / (d * d);
}

/** The CMOS model's lopsided curve through zero, as a secant gain. */
function analogCmosGain(x) {
  const b = ANALOG_CMOS_BIAS;
  if (x > -1e-9 && x < 1e-9) return analogClipSlope(b) / ANALOG_CMOS_SLOPE;
  return (analogClip(x + b) - analogClip(b)) / (x * ANALOG_CMOS_SLOPE);
}

/** Its slope at rest, divided out so the small-signal gain of the stage is one. */
const ANALOG_CMOS_SLOPE = analogClipSlope(ANALOG_CMOS_BIAS);

/**
 * The polar model's integrators running out of slew: the same curve with its knee pulled in,
 * so the amplifier is linear further and then stops harder.
 */
function analogSlewGain(x) {
  return analogClipGain(x * ANALOG_POLAR_KNEE);
}

// ---- the oversampling -------------------------------------------------------------------------

/**
 * Polyphase IIR half-bands: two chains of first-order allpasses in z^-2, whose sum is a lowpass
 * at a quarter of the faster rate. Coefficients from the classic elliptic design for this
 * structure, computed once and written down so both engines use the same numbers. Only a few
 * samples of delay in the audio band, which matters here because the device's dry/wet mixes the
 * filtered signal against the input.
 *
 * The first stage (base rate to twice it) has eight coefficients and a transition of 0.04 of
 * the doubled rate: 95 dB down from 0.27 of it. The second (twice to four times) only has to
 * keep what the first stage passes, so four coefficients and a transition of 0.12 do: 77 dB
 * down where anything would fold back under the base rate's Nyquist.
 */
const ANALOG_HALFBAND_A = Object.freeze([
  0.040633460924193260, 0.15050512902267460, 0.30075705599187408, 0.46077450496145061,
  0.60952431489618830, 0.73850384111885725, 0.84922381039206607, 0.94974278370500020,
]);
const ANALOG_HALFBAND_B = Object.freeze([
  0.070765948976184462, 0.25785307851345257, 0.51316757474879282, 0.81731735441713682,
]);

/** One direction of a half-band: the even coefficients on one path, the odd on the other. */
class AnalogHalfband {
  constructor(coefficients) {
    this.c = coefficients;
    this.half = coefficients.length / 2;
    // Each section keeps its last input and output.
    this.x = new Float64Array(coefficients.length);
    this.y = new Float64Array(coefficients.length);
  }

  reset() {
    this.x.fill(0);
    this.y.fill(0);
  }

  /** Runs one path (0 even coefficients, 1 odd) one step. */
  path(input, which) {
    const c = this.c;
    const x = this.x;
    const y = this.y;
    const half = this.half;
    let v = input;
    for (let i = 0; i < half; i++) {
      const at = which * half + i;
      const out = c[2 * i + which] * (v - y[at]) + x[at];
      x[at] = v;
      y[at] = out;
      v = out;
    }
    return v;
  }
}

// ---- the filter -------------------------------------------------------------------------------

class AnalogFilter {
  constructor(sampleRate, model = 0) {
    this.sampleRate = sampleRate;
    this.rate = sampleRate * 2;            // what the model runs at: set with the model
    this.four = false;
    this.model = -1;
    this.name = '';
    this.structure = 0;
    this.spec = ANALOG_SPECS.ladder;
    this.s = new Float64Array(4);          // the capacitors
    this.v = new Float64Array(6);          // where each curve's input was a sample ago
    this.fb = 0;                           // the diode ladder's feedback highpass
    this.fbG = 0;
    this.dcX = 0;                          // the CMOS model's output DC blocker
    this.dcY = 0;
    this.dcR = Math.max(0, 1 - (2 * Math.PI * ANALOG_DC_HZ) / sampleRate);
    this.upA = new AnalogHalfband(ANALOG_HALFBAND_A);
    this.downA = new AnalogHalfband(ANALOG_HALFBAND_A);
    this.upB = new AnalogHalfband(ANALOG_HALFBAND_B);
    this.downB = new AnalogHalfband(ANALOG_HALFBAND_B);
    this.cutoff = 1000;
    this.tuned = 1000;                     // the cutoff after the clamps, in Hz
    this.resonance = 0;
    this.drive = 1;
    this.morph = 0;
    this.wc = 0;                           // the prewarped corner, small-signal
    this.g = 0;                            // the integrator gain the model runs at
    this.k = 0;                            // the feedback (or damping) the resonance sets
    this.wl = 1;                           // lowpass, bandpass, highpass shares of the output
    this.wb = 0;
    this.wh = 0;
    this.morphs = false;
    this.setModel(model);
  }

  /** Clears every state: the capacitors, the curves' memory and the oversampler. */
  reset() {
    this.s.fill(0);
    this.v.fill(0);
    this.fb = 0;
    this.dcX = 0;
    this.dcY = 0;
    this.upA.reset();
    this.downA.reset();
    this.upB.reset();
    this.downB.reset();
  }

  /** Switches circuit. A different circuit is a different filter, so the state goes. */
  setModel(model) {
    const m = Math.min(ANALOG_MODELS.length - 1, Math.max(0, model | 0));
    if (m === this.model) return;
    this.model = m;
    this.name = ANALOG_MODELS[m];
    this.structure = ANALOG_STRUCTURE_INDEX[ANALOG_STRUCTURE[this.name]];
    this.spec = ANALOG_SPECS[this.name];
    this.four = this.spec.oversample === 4;
    this.rate = this.sampleRate * this.spec.oversample;
    this.morphs = ANALOG_MORPHING.includes(this.name);
    const hp = Math.tan((Math.PI * ANALOG_DIODE_FEEDBACK_HZ) / this.rate);
    this.fbG = hp / (1 + hp);
    this.reset();
    this.setCutoff(this.cutoff);
    this.setResonance(this.resonance);
    this.setMorph(this.morph);
  }

  setCutoff(hz) {
    this.cutoff = hz;
    const f = Math.min(this.sampleRate * ANALOG_MAX_CUTOFF, Math.max(ANALOG_MIN_CUTOFF_HZ, hz));
    this.tuned = f;
    let wc = Math.tan((Math.PI * f) / this.rate);
    if (this.structure === ANALOG_DIODE) wc /= ANALOG_DIODE_TUNE;
    this.wc = wc;
    this.g = wc;
  }

  setResonance(resonance) {
    const r = Math.min(1, Math.max(0, resonance));
    this.resonance = r;
    this.k = this.spec.top * r;
  }

  setDrive(drive) {
    this.drive = Math.max(0, drive);
  }

  /**
   * The response of the multimodes, 0..1. The state-variable model's knob runs lowpass, notch,
   * highpass (a notch is the two summed, halfway); the others run lowpass, bandpass, highpass.
   */
  setMorph(morph) {
    const m = Math.min(1, Math.max(0, morph));
    this.morph = m;
    if (!this.morphs) {
      this.wl = 1; this.wb = 0; this.wh = 0;
    } else if (this.name === 'statevar') {
      this.wb = 0;
      this.wl = m < 0.5 ? 1 : 2 - 2 * m;
      this.wh = m < 0.5 ? 2 * m : 1;
    } else if (m < 0.5) {
      this.wl = 1 - 2 * m; this.wb = 2 * m; this.wh = 0;
    } else {
      this.wl = 0; this.wb = 2 - 2 * m; this.wh = 2 * m - 1;
    }
  }

  /** Takes another's tuning, for the second channel of a pair. */
  follow(other) {
    if (other.model !== this.model) this.setModel(other.model);
    this.cutoff = other.cutoff;
    this.tuned = other.tuned;
    this.resonance = other.resonance;
    this.drive = other.drive;
    this.morph = other.morph;
    this.wc = other.wc;
    this.g = other.g;
    this.k = other.k;
    this.wl = other.wl;
    this.wb = other.wb;
    this.wh = other.wh;
  }

  /** One sample in, one out. */
  process(input) {
    const h = this.spec.headroom;
    const x = (input * this.drive) / h;
    const a = this.upA.path(x, 0);
    const b = this.upA.path(x, 1);
    let ya;
    let yb;
    if (this.four) {
      // In time order: a's two samples at four times the rate, then b's.
      const a0 = this.upB.path(a, 0);
      const a1 = this.upB.path(a, 1);
      const b0 = this.upB.path(b, 0);
      const b1 = this.upB.path(b, 1);
      const ya0 = this._step(a0);
      const ya1 = this._step(a1);
      const yb0 = this._step(b0);
      const yb1 = this._step(b1);
      ya = 0.5 * (this.downB.path(ya1, 0) + this.downB.path(ya0, 1));
      yb = 0.5 * (this.downB.path(yb1, 0) + this.downB.path(yb0, 1));
    } else {
      ya = this._step(a);
      yb = this._step(b);
    }
    let y = 0.5 * (this.downA.path(yb, 0) + this.downA.path(ya, 1)) * h;
    if (this.name === 'cmos') {
      const out = y - this.dcX + this.dcR * this.dcY;
      this.dcX = y;
      this.dcY = out;
      y = out;
    }
    const s = this.s;
    for (let i = 0; i < 4; i++) if (s[i] > -ANALOG_FLUSH && s[i] < ANALOG_FLUSH) s[i] = 0;
    if (this.fb > -ANALOG_FLUSH && this.fb < ANALOG_FLUSH) this.fb = 0;
    return y;
  }

  /**
   * One step of the circuit at its own rate, and the output amplifier's supply rails: whatever
   * the circuit does inside, what leaves it cannot swing further than they allow.
   */
  _step(x) {
    let y;
    switch (this.structure) {
      case ANALOG_CASCADE: y = this._cascade(x); break;
      case ANALOG_DIODE: y = this._diode(x); break;
      case ANALOG_SALLEN_KEY: y = this._sallenKey(x); break;
      default: y = this._stateVar(x); break;
    }
    return ANALOG_RAIL * analogClip(y / ANALOG_RAIL);
  }

  /**
   * Four one-poles in a loop. Each stage is y' = wc (A·prev - B·y), with A and B the curves'
   * secant gains: for the transistor ladder they are the curve at each side (tanh(prev) -
   * tanh(y)), for the OTA one curve of the difference (tanh(prev - y)). So every stage is affine
   * in the one before it, the whole chain is affine in the loop's input, and the loop is solved
   * for that input in closed form.
   */
  _cascade(x) {
    const g = this.g;
    const k = this.k;
    const s = this.s;
    const v = this.v;
    const ota = this.name === 'ota';
    // y_i = m_i·y_(i-1) + c_i, and the chain's end as G·u + S.
    let G = 1;
    let S = 0;
    let m0, m1, m2, m3, c0, c1, c2, c3;
    for (let i = 0; i < 4; i++) {
      let alpha;
      let beta;
      if (ota) {
        alpha = analogClipGain(v[i] - v[i + 1]);
        beta = alpha;
      } else {
        alpha = analogClipGain(v[i]);
        beta = analogClipGain(v[i + 1]);
      }
      const d = 1 / (1 + g * beta);
      const m = d * g * alpha;
      const c = d * s[i];
      G = m * G;
      S = m * S + c;
      if (i === 0) { m0 = m; c0 = c; } else if (i === 1) { m1 = m; c1 = c; } else if (i === 2) { m2 = m; c2 = c; } else { m3 = m; c3 = c; }
    }
    let u;
    if (ota) {
      // The input stage saturates the sum of the input and the feedback; the input is scaled up
      // by part of the feedback, as these chips' application circuits do, to keep the bass.
      const w = x * (1 + ANALOG_OTA_COMPENSATION * k);
      const a0 = analogClipGain(v[5]);
      u = (a0 * (w - k * S)) / (1 + a0 * k * G);
      v[5] = w - k * (G * u + S);
    } else {
      u = (x - k * S) / (1 + k * G);
    }
    v[0] = u;
    const y1 = m0 * u + c0;
    const y2 = m1 * y1 + c1;
    const y3 = m2 * y2 + c2;
    const y4 = m3 * y3 + c3;
    s[0] = 2 * y1 - s[0];
    s[1] = 2 * y2 - s[1];
    s[2] = 2 * y3 - s[2];
    s[3] = 2 * y4 - s[3];
    v[1] = y1; v[2] = y2; v[3] = y3; v[4] = y4;
    return y4;
  }

  /**
   * The diode ladder: y1' = wc (T(u - y1) - T(y1 - y2)), the middle two the same one place up,
   * and y4' = 2 wc T(y3 - y4) for the half-size top capacitor. Tridiagonal once linearized, so it
   * is solved from the top down as y_i = alpha_i·y_(i-1) + beta_i and then the loop closed at the
   * bottom. The feedback goes through a coupling highpass on its way back.
   */
  _diode(x) {
    const g = this.g;
    const k = this.k;
    const s = this.s;
    const v = this.v;
    const e1 = analogClipGain(v[0] - v[1]);
    const e2 = analogClipGain(v[1] - v[2]);
    const e3 = analogClipGain(v[2] - v[3]);
    const e4 = analogClipGain(v[3] - v[4]);
    const g4 = 2 * g * e4;
    const a4 = g4 / (1 + g4);
    const b4 = s[3] / (1 + g4);
    const d3 = 1 + g * e3 + g * e4 - g * e4 * a4;
    const a3 = (g * e3) / d3;
    const b3 = (s[2] + g * e4 * b4) / d3;
    const d2 = 1 + g * e2 + g * e3 - g * e3 * a3;
    const a2 = (g * e2) / d2;
    const b2 = (s[1] + g * e3 * b3) / d2;
    const d1 = 1 + g * e1 + g * e2 - g * e2 * a2;
    const a1 = (g * e1) / d1;
    const b1 = (s[0] + g * e2 * b2) / d1;
    const A = a4 * a3 * a2 * a1;
    const B = a4 * (a3 * (a2 * b1 + b2) + b3) + b4;
    // The highpass in the loop is (1 - G)(y4 - its state), affine in y4 like everything else.
    const hp = 1 - this.fbG;
    const drive = x * (1 + ANALOG_DIODE_COMPENSATION * k);
    const u = (drive - k * hp * (B - this.fb)) / (1 + k * hp * A);
    const y1 = a1 * u + b1;
    const y2 = a2 * y1 + b2;
    const y3 = a3 * y2 + b3;
    const y4 = a4 * y3 + b4;
    s[0] = 2 * y1 - s[0];
    s[1] = 2 * y2 - s[1];
    s[2] = 2 * y3 - s[2];
    s[3] = 2 * y4 - s[3];
    const step = (y4 - this.fb) * this.fbG;
    this.fb = this.fb + 2 * step;
    v[0] = u; v[1] = y1; v[2] = y2; v[3] = y3; v[4] = y4;
    return y4;
  }

  /**
   * The Sallen-Key two-pole: node a between the two resistors, node b on the second capacitor,
   * the first capacitor's far end lifted by K times the output through a clipper. Fed at the
   * resistor it is a lowpass, at the first capacitor a bandpass, at the second a highpass (with
   * twice the bandpass taken back off), which is how the morph picks a response.
   *
   *   c1 = a - K·F(b) - xb,  c1' = wc (T(xl - a) - T(a - b))
   *   c2 = b - xh,           c2' = wc  T(a - b)
   *
   * For `sallen` the first T is the input stage running out of room and the second a plain
   * resistor; for `diodepair` both are diode pairs.
   */
  _sallenKey(x) {
    const g = this.g;
    const s = this.s;
    const v = this.v;
    const xl = this.wl * x;
    const xb = (this.wb - 2 * this.wh) * x;
    const xh = this.wh * x;
    const diodepair = this.name === 'diodepair';
    const e1 = analogClipGain(v[0] - v[1]);
    const e2 = diodepair ? analogClipGain(v[1] - v[2]) : 1;
    const f = analogClipGain(v[2] * (diodepair ? ANALOG_DIODEPAIR_CLIP : ANALOG_SALLEN_CLIP));
    const kf = this.k * f;
    const p = (g * e2) / (1 + g * e2);
    const q = (s[1] + xh) / (1 + g * e2);
    const a = (s[0] + g * e1 * xl + xb + (g * e2 + kf) * q) / (1 + g * e1 + g * e2 - (g * e2 + kf) * p);
    const b = p * a + q;
    s[0] = 2 * (a - kf * b - xb) - s[0];
    s[1] = 2 * (b - xh) - s[1];
    v[0] = xl; v[1] = a; v[2] = b;
    return b;
  }

  /**
   * The state-variable two-pole: hp = x - 2·bp + k·R(bp) - lp, bp' = wc T(hp), lp' = wc T(bp).
   * The resonance is a positive feedback of the band against a fixed damping of two, through a
   * curve R, so a loud band feeds itself less and the ring settles at a level of its own. T is
   * the integrators' amplifier and R the resonance path's: soft for `statevar`, lopsided for
   * `cmos`, a hard slew limit for `polar`.
   */
  _stateVar(x) {
    const g = this.g;
    const s = this.s;
    const v = this.v;
    let a1;
    let a2;
    let c;
    if (this.name === 'cmos') {
      a1 = analogCmosGain(v[0]);
      a2 = analogCmosGain(v[1]);
      c = analogCmosGain(v[1] * ANALOG_RING_KNEE);
    } else if (this.name === 'polar') {
      a1 = analogSlewGain(v[0]);
      a2 = analogSlewGain(v[1]);
      c = analogSlewGain(v[1] * ANALOG_RING_KNEE);
    } else {
      a1 = analogClipGain(v[0]);
      a2 = analogClipGain(v[1]);
      c = analogClipGain(v[1]);
    }
    const k = 2 - this.k * c;
    const hp = (x - k * s[0] - s[1] - g * a2 * s[0]) / (1 + k * g * a1 + g * g * a1 * a2);
    const bp = s[0] + g * a1 * hp;
    const lp = s[1] + g * a2 * bp;
    s[0] = 2 * bp - s[0];
    s[1] = 2 * lp - s[1];
    v[0] = hp; v[1] = bp;
    return this.wl * lp + this.wb * bp + this.wh * hp;
  }

  /**
   * The small-signal response at `hz`, complex: every curve at its slope through zero, which
   * is what the circuit does to a quiet signal. The feedback is held just under where the loop
   * starts to oscillate, since past there a magnitude response does not exist - the real filter
   * is singing at its own level, which no linear picture can show.
   */
  transfer(hz) {
    const w = Math.tan((Math.PI * Math.min(hz, this.rate * 0.4999)) / this.rate) / this.wc;
    const { onset } = this.spec;
    let den;
    let num;
    switch (this.structure) {
      case ANALOG_CASCADE: {
        const k = Math.min(this.k, onset * 0.985);
        // (1 + jw)^4 + k, and the OTA's input share on top.
        const w2 = w * w;
        den = { re: 1 - 6 * w2 + w2 * w2 + k, im: 4 * w - 4 * w2 * w };
        num = { re: this.name === 'ota' ? 1 + ANALOG_OTA_COMPENSATION * k : 1, im: 0 };
        return analogDiv(num, den);
      }
      case ANALOG_DIODE: {
        const k = Math.min(this.k, onset * 0.985);
        // From the top down, as the solver does, with each capacitor's (s + coupling).
        const sj = { re: 0, im: w };
        const a4 = analogDiv({ re: 2, im: 0 }, { re: 2, im: w });
        const a3 = analogDiv({ re: 1, im: 0 }, { re: 2 - a4.re, im: w - a4.im });
        const a2 = analogDiv({ re: 1, im: 0 }, { re: 2 - a3.re, im: w - a3.im });
        const a1 = analogDiv({ re: 1, im: 0 }, { re: 2 - a2.re, im: w - a2.im });
        const A = analogMul(analogMul(a4, a3), analogMul(a2, a1));
        // The coupling highpass, s / (s + its corner in stage-corner units).
        const corner = this.fbG / (1 - this.fbG) / this.wc;
        const hpf = analogDiv(sj, { re: corner, im: w });
        const loop = analogMul(A, hpf);
        const gain = 1 + ANALOG_DIODE_COMPENSATION * k;
        return analogDiv({ re: A.re * gain, im: A.im * gain }, { re: 1 + k * loop.re, im: k * loop.im });
      }
      case ANALOG_SALLEN_KEY: {
        const k = Math.min(this.k, onset * 0.985);
        den = { re: 1 - w * w, im: (3 - k) * w };
        num = { re: this.wl - this.wh * w * w, im: this.wb * w };
        return analogDiv(num, den);
      }
      default: {
        const k = 2 - Math.min(this.k, onset * 0.985);
        den = { re: 1 - w * w, im: k * w };
        num = { re: this.wl - this.wh * w * w, im: this.wb * w };
        return analogDiv(num, den);
      }
    }
  }
}

function analogMul(a, b) {
  return { re: a.re * b.re - a.im * b.im, im: a.re * b.im + a.im * b.re };
}

function analogDiv(a, b) {
  const d = b.re * b.re + b.im * b.im;
  return { re: (a.re * b.re + a.im * b.im) / d, im: (a.im * b.re - a.re * b.im) / d };
}

// ---- src/dsp/filters.mjs -----------------------------------------
// The two filters the wavetable synth offers, and the one-pole used as a tone control.
//
// The circuit-modeled modes - the ladder among them - are their own module (analog.mjs); this
// one fronts them through MultiFilter.
//
// A state-variable filter for the clean modes and a four-pole ladder for the drum. Both
// are written per-sample and allocation-free, and both take their cutoff as a frequency in Hz
// so an envelope or an LFO can move it at audio rate without a lookup table in between.
//
// Both are the topology-preserving form rather than the textbook one, and for the same reason:
// the naive forms' cutoff drifts from where it was asked for as it approaches a quarter of the
// sample rate, so a filter envelope sweeping to the top of its range either sounds wrong or
// stops being a filter. The ladder used to be the naive cascade, and above five kilohertz its
// corner sat well above the number on the knob with the slope collapsed under it.


/**
 * Every response the filter offers, in panel order.
 *
 * SLOPES ARE SEPARATE ENTRIES rather than a second knob. A slope only means anything on the
 * pass modes - a notch has no slope, a comb has no slope - so a knob for it would be a control
 * that does nothing most of the time, and picking "lowpass 24" says in one gesture what a mode
 * plus a slope says in two. `lowpass`, `highpass` and `bandpass` keep their old names and their
 * old sound, which is twelve decibels an octave; the numbered ones are the other slopes.
 *
 * The three after the ladder are the responses that are not a slope at all. Each is an ordinary
 * textbook structure - a comb is a delay summed with itself, an allpass cascade is what every
 * phaser is built from, a formant bank is three bandpasses at the resonances of a vowel - and
 * they are here because a filter with only the four classical shapes is the one part of this
 * synth with nothing to discover in it.
 *
 * The ladder and everything after the formant bank are circuit models (see analog.mjs): each
 * one a classic analog filter's own equations, with the saturation and the resonance that
 * circuit has. They are listed by their model names, and in the model list's order.
 *
 * A song stores an enum by its LABEL (see valueToArg), so this list can be reordered without
 * changing what anything plays.
 */
const FILTER_MODES = Object.freeze([
  'lowpass 6', 'lowpass', 'lowpass 24',
  'highpass 6', 'highpass', 'highpass 24',
  'bandpass', 'bandpass 24',
  'notch', 'peak',
  'ladder',
  'comb', 'allpass', 'formant',
  ...ANALOG_MODELS.filter((name) => name !== 'ladder'),
]);

/** For each mode, the circuit model it runs, or -1 for the modes that are not one. */
const ANALOG_OF_MODE = Object.freeze(FILTER_MODES.map((name) => ANALOG_MODELS.indexOf(name)));

/** The modes the Drive control reaches: every circuit model, and nothing else. */
const DRIVEN_MODES = Object.freeze(FILTER_MODES.filter((name) => ANALOG_MODELS.includes(name)));

/** The modes the Morph control reaches: the circuit models that are multimodes. */
const MORPHING_MODES = Object.freeze([...ANALOG_MORPHING]);

/** What each mode is made of, which is what MultiFilter switches on. */
const MODE = Object.freeze(Object.fromEntries(FILTER_MODES.map((name, i) => [name, i])));

/** The modes built from two state-variable sections in series rather than one. */
const CASCADED = new Set([
  FILTER_MODES.indexOf('lowpass 24'),
  FILTER_MODES.indexOf('highpass 24'),
  FILTER_MODES.indexOf('bandpass 24'),
]);

/** The five vowels the formant mode sweeps through, as the first three resonances of each. */
const FORMANTS = Object.freeze([
  [270, 2290, 3010],   // ee
  [530, 1840, 2480],   // eh
  [730, 1090, 2440],   // ah
  [570, 840, 2410],    // oh
  [300, 870, 2240],    // oo
]);

const MIN_CUTOFF_HZ = 20;

/**
 * The four shapes the state-variable core itself offers, which is NOT the device's mode list:
 * `Svf#next` switches on these and MultiFilter maps the device's modes onto them. Two lists
 * because the core has four responses and the device offers fourteen, and conflating them made
 * a reordering of the panel's list silently change which filter ran.
 */
const SVF_MODES = Object.freeze(['lowpass', 'highpass', 'bandpass', 'notch']);

/**
 * A topology-preserving state-variable filter: lowpass, highpass, bandpass and notch off the
 * same two integrators, so switching mode costs nothing and never re-tunes the filter.
 */
class Svf {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.ic1 = 0;
    this.ic2 = 0;
    this.g = 0;
    this.k = 2;
    this.a1 = 0;
    this.a2 = 0;
    this.a3 = 0;
    this.setCutoff(1000, 0);
  }

  reset() {
    this.ic1 = 0;
    this.ic2 = 0;
  }

  /**
   * `resonance` is 0..1, mapped so that 1 is just short of self-oscillation. The cutoff is
   * clamped below Nyquist because the prewarp's tangent goes to infinity there, and a filter
   * asked for an impossible cutoff should sit at the top of its range rather than produce NaN.
   */
  setCutoff(hz, resonance) {
    const nyquist = this.sampleRate * 0.5;
    const f = Math.min(nyquist * 0.99, Math.max(MIN_CUTOFF_HZ, hz));
    const g = Math.tan((Math.PI * f) / this.sampleRate);
    const k = 2 - 1.98 * Math.min(1, Math.max(0, resonance));
    this.g = g;
    this.k = k;
    this.a1 = 1 / (1 + g * (g + k));
    this.a2 = g * this.a1;
    this.a3 = g * this.a2;
  }

  /**
   * Takes another filter's tuning. A stereo voice retunes its left filter per sample and has the
   * right one follow, so the pair costs one tangent per sample rather than two.
   */
  follow(other) {
    this.g = other.g;
    this.k = other.k;
    this.a1 = other.a1;
    this.a2 = other.a2;
    this.a3 = other.a3;
  }

  /** One sample, in the given mode (an index into FILTER_MODES). */
  next(input, mode) {
    const v3 = input - this.ic2;
    const v1 = this.a1 * this.ic1 + this.a2 * v3;
    const v2 = this.ic2 + this.a2 * this.ic1 + this.a3 * v3;
    this.ic1 = 2 * v1 - this.ic1;
    this.ic2 = 2 * v2 - this.ic2;
    switch (mode) {
      case 1: return input - this.k * v1 - v2;          // highpass
      case 2: return v1;                                 // bandpass
      case 3: return input - this.k * v1;                // notch
      default: return v2;                                // lowpass
    }
  }
}

/** A cheap, well-behaved saturator for the ladder's feedback path. */
const softClip = (x) => {
  if (x < -3) return -1;
  if (x > 3) return 1;
  const x2 = x * x;
  return (x * (27 + x2)) / (27 + 9 * x2);
};

/**
 * A four-pole ladder lowpass with a saturated feedback path, one saturator for the whole loop.
 * The Drum's filter; the Filter device's `ladder` mode is the circuit model in analog.mjs, which
 * saturates every stage and sings at the top of its resonance.
 *
 * Four one-pole stages in the topology-preserving form, with the feedback solved at the loop's
 * input rather than taken one sample late: what the stages would put out with no new input is
 * known from their states, so the input the loop actually sees is found in closed form and the
 * saturation is applied to that. The result is a ladder whose resonance peak lands on the
 * number the cutoff says, at any cutoff the synth can ask for.
 *
 * It is a ladder, so at the corner it sits twelve decibels down where the clean lowpass sits
 * six: four poles at one frequency, as the circuit has. That is not a calibration error and the
 * descriptor says so.
 */
class Ladder {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.s = new Float64Array(4);
    this.G = 0;
    this.G4 = 0;
    this.k = 0;
    this.drive = 1;
    this.setCutoff(1000, 0);
  }

  reset() {
    this.s.fill(0);
  }

  setCutoff(hz, resonance) {
    const nyquist = this.sampleRate * 0.5;
    const f = Math.min(nyquist * 0.49, Math.max(MIN_CUTOFF_HZ, hz));
    const g = Math.tan((Math.PI * f) / this.sampleRate);
    const G = g / (1 + g);
    this.G = G;
    this.G4 = G * G * G * G;
    // Four is where the linear loop self-oscillates; the top of the knob stops just short of it,
    // and the saturation keeps what happens near there bounded.
    this.k = 4 * Math.min(1, Math.max(0, resonance)) * 0.98;
  }

  /** Takes another ladder's tuning and drive, for the same reason Svf#follow exists. */
  follow(other) {
    this.G = other.G;
    this.G4 = other.G4;
    this.k = other.k;
    this.drive = other.drive;
  }

  next(input) {
    const G = this.G;
    const s = this.s;
    // What the four stages would output right now with nothing new at the input.
    const settled = (1 - G) * (G * G * G * s[0] + G * G * s[1] + G * s[2] + s[3]);
    const u = softClip((input * this.drive - this.k * settled) / (1 + this.k * this.G4));
    let x = u;
    for (let i = 0; i < 4; i++) {
      const v = (x - s[i]) * G;
      const y = v + s[i];
      s[i] = y + v;
      x = y;
    }
    return x;
  }
}

/**
 * A one-pole lowpass, used where a filter is a tone control rather than an instrument: the
 * distortion unit's tone knob, the smoothing on a control that would otherwise step.
 */
class OnePole {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.a = 1;
    this.target = 1;
    this.steps = 0;
    this.z = 0;
    this.setCutoff(20000);
  }

  reset() {
    this.z = 0;
  }

  /** The coefficient for a corner, without touching the filter. */
  _coefficient(hz) {
    const nyquist = this.sampleRate * 0.5;
    const f = Math.min(nyquist * 0.99, Math.max(1, hz));
    return 1 - Math.exp((-2 * Math.PI * f) / this.sampleRate);
  }

  /** Jumps to a corner. For a filter being built, or one whose corner never moves. */
  setCutoff(hz) {
    this.a = this._coefficient(hz);
    this.target = this.a;
    this.steps = 0;
  }

  /**
   * Aims at a corner, reached over `steps` samples. A tone control is usually set and left, but
   * a tone control INSIDE A FEEDBACK PATH - a delay's, a distortion's - is heard on every
   * repeat, and a corner that jumps once a block is a buzz riding the sweep.
   */
  glideTo(hz, steps) {
    this.target = this._coefficient(hz);
    this.steps = Math.max(0, steps | 0);
    if (this.steps === 0) this.a = this.target;
  }

  next(input) {
    if (this.steps > 0) {
      this.a += (this.target - this.a) / this.steps;
      this.steps -= 1;
    }
    this.z += this.a * (input - this.z);
    return this.z;
  }
}

/**
 * A DC blocker. A waveshaper fed an asymmetric drive puts an offset on its output, and an
 * offset costs headroom on every later stage without being audible itself - so distortion modes
 * that bias the signal on purpose run their output through one of these.
 */
class DcBlocker {
  constructor(sampleRate, cutoffHz = 20) {
    // The pole has to be placed in radians per sample, not cycles: leaving out the 2*pi puts
    // the corner at about 3 Hz instead of 20, and an offset then takes a quarter of a second to
    // settle rather than a few milliseconds.
    this.r = Math.max(0, 1 - (2 * Math.PI * cutoffHz) / sampleRate);
    this.x1 = 0;
    this.y1 = 0;
  }

  reset() {
    this.x1 = 0;
    this.y1 = 0;
  }

  next(input) {
    const y = input - this.x1 + this.r * this.y1;
    this.x1 = input;
    this.y1 = y;
    return y;
  }
}

/** One first-order allpass: unity gain, a phase turn that sweeps with the coefficient. */
class Allpass1 {
  constructor() { this.a = 0; this.x1 = 0; this.y1 = 0; }
  reset() { this.x1 = 0; this.y1 = 0; }
  next(x) {
    const y = this.a * (x + this.y1) - this.x1;
    this.x1 = x;
    this.y1 = y;
    return y;
  }
}

/** How long the comb mode's delay line is, in seconds: the lowest note it can be tuned to. */
const COMB_MAX_SEC = 0.05;

/** How many allpass sections the allpass mode runs. Four is two notches, which is the sound. */
const ALLPASS_STAGES = 4;

/**
 * Every filter response behind one interface, so a device switching mode does not switch code.
 *
 * The four classical shapes and their slopes come off a state-variable core; the circuit models
 * share one AnalogFilter, which switches circuit with the mode; the rest are each a small
 * structure of their own, held here and idle until the
 * mode picks them. That is the tradeoff this class makes deliberately: a few hundred bytes of
 * state per channel that is mostly asleep, against one filter that can be any of these without
 * the device knowing which. Everything is tuned per sample, exactly as the core is, so a
 * swept cutoff on the comb or the formant bank is as smooth as a swept lowpass.
 */
class MultiFilter {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    // Two state-variable sections: the first is 12 dB, the pair in series is 24.
    this.svf = [new Svf(sampleRate), new Svf(sampleRate)];
    this.analog = new AnalogFilter(sampleRate);
    this.one = 0;                       // the one-pole's state, for the 6 dB slopes
    this.oneA = 0;
    this.apFb = 0;                      // what the allpass chain last put out, for its feedback
    this.comb = new Float32Array(Math.ceil(COMB_MAX_SEC * sampleRate) + 4);
    this.combAt = 0;
    this.combLen = 100;
    this.combFb = 0;
    this.allpass = Array.from({ length: ALLPASS_STAGES }, () => new Allpass1());
    this.apGain = 0;
    // Three bandpasses for the formant mode, and the mix that picks the vowel.
    this.formant = [new Svf(sampleRate), new Svf(sampleRate), new Svf(sampleRate)];
    this.formantGain = new Float64Array(3);
  }

  reset() {
    for (const f of this.svf) f.reset();
    this.analog.reset();
    this.one = 0;
    this.apFb = 0;
    this.comb.fill(0);
    this.combAt = 0;
    for (const a of this.allpass) a.reset();
    for (const f of this.formant) f.reset();
  }

  set drive(value) { this.analog.setDrive(value); }

  /** The circuit models' multimode response, 0..1 (see AnalogFilter#setMorph). */
  set morph(value) { this.analog.setMorph(value); }

  /** Tunes whichever structure the mode uses. Cheap for the ones it does not. */
  setCutoff(hz, resonance, mode) {
    // The circuit models run oversampled, so they take their own ceiling rather than this one.
    const model = ANALOG_OF_MODE[mode] ?? -1;
    if (model >= 0) {
      this.analog.setModel(model);
      this.analog.setCutoff(hz);
      this.analog.setResonance(resonance);
      return;
    }
    const nyquist = this.sampleRate * 0.5;
    const f = Math.min(nyquist * 0.49, Math.max(MIN_CUTOFF_HZ, hz));
    switch (mode) {
      case MODE['lowpass 6']:
      case MODE['highpass 6']:
        this.oneA = 1 - Math.exp((-2 * Math.PI * f) / this.sampleRate);
        return;
      case MODE.comb: {
        // The cutoff IS the comb's pitch: the delay is one period of it, so the teeth land on
        // that note and its harmonics. Resonance is the feedback, which is what makes it ring.
        this.combLen = Math.min(this.comb.length - 2, Math.max(2, this.sampleRate / f));
        this.combFb = Math.min(0.98, Math.max(0, resonance)) * 0.98;
        return;
      }
      case MODE.allpass: {
        // The coefficient every section turns on. One expression rather than a tangent per
        // stage: they are all tuned to the same corner, which is what makes the notches move
        // together.
        const t = Math.tan((Math.PI * f) / this.sampleRate);
        const a = (t - 1) / (t + 1);
        for (const stage of this.allpass) stage.a = a;
        // Feedback round the chain deepens the notches. Kept well under one: an allpass cascade
        // has unity gain, so anything near it rings without ever running out of energy.
        this.apGain = Math.min(1, Math.max(0, resonance)) * 0.7;
        return;
      }
      case MODE.formant: {
        // The cutoff sweeps THROUGH the vowels rather than moving one of them: the five are laid
        // out across the range and the two either side of the position are blended.
        const at = (Math.log(f / MIN_CUTOFF_HZ) / Math.log((nyquist * 0.49) / MIN_CUTOFF_HZ)) * (FORMANTS.length - 1);
        const lo = Math.min(FORMANTS.length - 1, Math.max(0, Math.floor(at)));
        const hi = Math.min(FORMANTS.length - 1, lo + 1);
        const mix = at - lo;
        // Narrower as the resonance goes up, which is what makes a vowel read as a vowel.
        const q = 0.35 + 0.6 * Math.min(1, Math.max(0, resonance));
        for (let i = 0; i < 3; i++) {
          const center = FORMANTS[lo][i] + (FORMANTS[hi][i] - FORMANTS[lo][i]) * mix;
          this.formant[i].setCutoff(center, q);
          // The higher resonances are quieter in a real vowel, or the bank sounds like a whistle.
          this.formantGain[i] = i === 0 ? 1 : i === 1 ? 0.5 : 0.25;
        }
        return;
      }
      default: {
        this.svf[0].setCutoff(f, resonance);
        // THE SECOND SECTION OF A CASCADE TAKES NO RESONANCE.
        //
        // Two resonant sections in series multiply their peaks: at the top of the knob each one
        // lifts the corner by a factor of fifty, and the pair by two and a half thousand, which
        // is not a filter with a lot of resonance - it is a filter that destroys the track. One
        // resonant section and one flat one is the usual four-pole arrangement, and it keeps the
        // slope while the peak stays a peak.
        if (CASCADED.has(mode)) this.svf[1].setCutoff(f, 0);
        return;
      }
    }
  }

  /** Takes another's tuning, for the other channel of a stereo pair. */
  follow(other) {
    this.svf[0].follow(other.svf[0]);
    this.svf[1].follow(other.svf[1]);
    this.analog.follow(other.analog);
    this.oneA = other.oneA;
    this.combLen = other.combLen;
    this.combFb = other.combFb;
    for (let i = 0; i < ALLPASS_STAGES; i++) this.allpass[i].a = other.allpass[i].a;
    this.apGain = other.apGain;
    for (let i = 0; i < 3; i++) {
      this.formant[i].follow(other.formant[i]);
      this.formantGain[i] = other.formantGain[i];
    }
  }

  /** Reads the comb line `len` samples back, interpolated, so a swept pitch glides. */
  _combRead(len) {
    const n = this.comb.length;
    const at = this.combAt - len;
    const wrapped = at - Math.floor(at / n) * n;
    const i = Math.floor(wrapped);
    const frac = wrapped - i;
    const a = this.comb[i];
    const b = this.comb[(i + 1) % n];
    return a + (b - a) * frac;
  }

  next(x, mode) {
    if ((ANALOG_OF_MODE[mode] ?? -1) >= 0) return this.analog.process(x);
    switch (mode) {
      case MODE['lowpass 6']:
        this.one += this.oneA * (x - this.one);
        return this.one;
      case MODE['highpass 6']:
        this.one += this.oneA * (x - this.one);
        return x - this.one;
      case MODE['lowpass 24']:
        return this.svf[1].next(this.svf[0].next(x, 0), 0);
      case MODE['highpass 24']:
        return this.svf[1].next(this.svf[0].next(x, 1), 1);
      case MODE['bandpass 24']:
        // Normalized at each stage - see the note on the bandpass below.
        return this.svf[1].next(this.svf[0].next(x, 2) * this.svf[0].k, 2) * this.svf[1].k;
      case MODE.peak: {
        // The bandpass added back to the signal: a resonant lift at the cutoff that leaves
        // everything either side of it alone. The resonance is the SIZE of the lift here rather
        // than its sharpness, which is what a peak control means everywhere else.
        const band = this.svf[0].next(x, 2) * this.svf[0].k;
        return x + band * (2 - this.svf[0].k) * 4;
      }
      case MODE.comb: {
        const read = this._combRead(this.combLen);
        const write = x + read * this.combFb;
        this.comb[this.combAt] = Number.isFinite(write) ? write : 0;
        this.combAt = (this.combAt + 1) % this.comb.length;
        // Summed rather than replaced: a comb is the sound of a signal against a copy of itself.
        return (x + read) * 0.5;
      }
      case MODE.allpass: {
        let y = x + this.apFb * (this.apGain ?? 0);
        for (const stage of this.allpass) y = stage.next(y);
        this.apFb = Number.isFinite(y) ? y : 0;
        // The phase-turned copy against the original, which is where the notches come from.
        return (x + y) * 0.5;
      }
      case MODE.formant: {
        let y = 0;
        for (let i = 0; i < 3; i++) y += this.formant[i].next(x, 2) * this.formantGain[i];
        return y * 1.4;
      }
      case MODE.highpass:
        return this.svf[0].next(x, 1);
      case MODE.bandpass:
        // NORMALIZED: the state-variable core's bandpass output is the textbook one, whose gain
        // at the center is one over the damping - so turning the resonance up made the band
        // thirty decibels louder as well as narrower, which is a volume control nobody asked
        // for and a clipped track at the top of the knob. Multiplying by the damping puts the
        // center at unity at every setting, and the resonance does the one thing it says.
        return this.svf[0].next(x, 2) * this.svf[0].k;
      case MODE.notch:
        return this.svf[0].next(x, 3);
      default:
        return this.svf[0].next(x, 0);
    }
  }
}

// ---- src/devices/analog.mjs --------------------------------------
// The Analog synth: two oscillators, a sub and noise into an analog filter circuit with its own
// envelope, on every voice.
//
// THE OSCILLATORS are a saw, a square with a width, a triangle or a sine each, drawn
// band-limited: every jump in a saw or a square and every corner of a triangle is placed at its
// exact fraction of a sample and corrected with a windowed sinc (dsp/blep.mjs), so a high note
// does not fold back. Osc 2 sits Semi and Detune away from osc 1, and Sync restarts it at every
// cycle of osc 1 - each restart a jump of its own, drawn the same way. Mix crossfades the two.
// The sub is a square an octave below osc 1, flipped at osc 1's own cycle, and noise is white.
// Everything is summed into one line and comes out BLEP_HALF samples late.
//
// DRIFT. Each oscillator wanders a few cents on its own, as a pair of analog oscillators never
// quite agree: a smoothed random walk a voice keeps from note to note, seeded, so a render plays
// the same twice and on both engines.
//
// ONE FILTER PER VOICE, which is the exception to the synths being filterless (see
// dsp/voice.mjs): a chain filter is shared by every voice and follows one envelope, and an
// envelope per note is the sound of this instrument. Cutoff moves with the note (Key Track, from
// middle C) and with the filter envelope (Env Amount, in semitones, either way); Velocity sets how
// much a note's velocity scales that envelope, so a harder note opens it further.
//
// THE FILTER is a circuit model from dsp/analog.mjs, the same ones the Filter device's analog
// modes run: Filter Type picks the model (ANALOG_MODELS, in Filter's order), Drive is the level
// into it, Morph the response of the multimode ones. A voice talks to it only through
// setModel, setCutoff, setResonance, setDrive, setMorph, process and reset; the model has its own
// saturation and its own oversampling.
//
// MONO. With Voices at one the synth is a monosynth: a note played while another is held slides
// to it over Glide without starting either envelope again, and letting go of it slides back to the
// note still held. A note on its own starts both envelopes. With more voices each note takes a
// voice, and Glide slides a voice from whatever it was last playing.
//
// Translated line for line into native/devices/own/analog.cc for the desktop, and held to it by
// native-device-parity.test.mjs. Everything is computed in double and written to the output once
// per voice per sample, as the C++ does.


/** The oscillator shapes, in the order the controls list them. */
const ANALOG_SHAPES = Object.freeze(['saw', 'square', 'triangle', 'sine']);
const ANALOG_SAW = 0;
const ANALOG_SQUARE = 1;
const ANALOG_TRIANGLE = 2;

/** How far the Voices knob reaches, which is no most (see the Wavetable's VOICES_KNOB). */
const ANALOG_VOICES_KNOB = 128;
/** The note Key Track turns on: at middle C the cutoff is the knob's. */
const ANALOG_TRACK_NOTE = 60;
/** Drift at one: how far, in cents, an oscillator wanders either way. */
const ANALOG_DRIFT_CENTS = 12;
/** How often the wander picks somewhere new to go, and how slowly it gets there. */
const ANALOG_DRIFT_STEP_SEC = 0.4;
const ANALOG_DRIFT_SMOOTH_SEC = 0.2;
/** The narrowest a pulse gets, as a share of the cycle, at either end of Width. */
const ANALOG_MIN_WIDTH = 0.02;
/** The highest an oscillator plays, as a share of the sample rate: past it, it is held there. */
const ANALOG_TOP = 0.45;
/** A voice's level against the controls, as the other synths'. */
const ANALOG_VOICE_GAIN = 0.5;
/** How close a glide gets, in semitones, before it lands. */
const ANALOG_GLIDE_LAND = 1e-6;
/** The most notes a monosynth remembers being held. */
const ANALOG_HELD = 64;
const ANALOG_TWO_PI = 2 * Math.PI;

const analogClamp01 = (x) => Math.min(1, Math.max(0, x));

/** The Filter Type options: the circuit models, in the Filter device's order. */
const ANALOG_FILTER_TYPES = ANALOG_MODELS;

/** A filter type as the Filter device's mode of the same circuit, for the panel's picture. */
function analogResponse(type) {
  const t = Math.min(ANALOG_MODELS.length - 1, Math.max(0, Math.round(type)));
  return FILTER_MODES.indexOf(ANALOG_MODELS[t]);
}

/** A filter type's index by name, for the presets. */
const ANALOG_TYPE = Object.freeze(Object.fromEntries(ANALOG_MODELS.map((name, i) => [name, i])));

