/**
 * One stream of xorshift32 with unsigned shifts throughout, which is the same sequence here (with
 * `>>> 0` after each shift that can carry into the sign) and in C++ (on an unsigned int).
 */
class DrumNoise {
  constructor() { this.state = 1; }
  seed(s) { this.state = (s >>> 0) || 1; }
  white() {
    let x = this.state;
    x ^= x << 13; x >>>= 0;
    x ^= x >>> 17; x >>>= 0;
    x ^= x << 5; x >>>= 0;
    this.state = x;
    return x / 2147483648 - 1;
  }
}

class DrumVoice {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.phase = new Float64Array(DRUM_MODES);
    this.env = new Float64Array(DRUM_MODES);
    this.ratios = new Float64Array(DRUM_MODES);
    this.levels = new Float64Array(DRUM_MODES);
    this.gains = new Float64Array(DRUM_MODES);
    this.burstAt = new Float64Array(DRUM_BURSTS);
    this.rng = new DrumNoise();
    this.filter = new Svf(sampleRate);
    this.note = -1;
    this.velocity = 1;
    this.age = 0;
    this.active = false;
    // What the hit was struck with (see noteOn).
    this.norm = 1;
    this.pitch = 0;
    this.drop = 0;
    this.dropG = 0;
    this.clickLevel = 0;
    this.mix = 0;
    this.toneGain = 1;
    this.tailG = 0;
    this.burstG = 0;
    this.slowLevel = 0;
    this.slowG = 0;
    this.drive = 0;
    this.fm = 0;
    this.fmRatio = 1;
    this.cutoff = DRUM_CUTOFF_TOP;
    this.resonance = 0;
    this.sweep = 0;
    this.sweepG = 0;
    this.filtered = false;
    this.topRatio = 0;
    this.ladder = new Ladder(sampleRate);
    this.reset();
  }

  reset() {
    this.phase.fill(0);
    this.env.fill(0);
    this.t = 0;
    this.dropEnv = 0;
    this.burst = 0;
    this.tail = 0;
    this.slow = 0;
    this.nextBurst = DRUM_BURSTS;
    this.tailAt = 0;
    this.tailOn = true;
    this.click = 0;
    this.lastWhite = 0;
    this.sweepEnv = 0;
    this.fmPhase = 0;
    this.filter.reset();
    this.ladder.reset();
  }

  /**
   * Starts a hit, reading every sound control at sample `j` of the block's values `p` - the
   * strike. The hit keeps them for as long as it rings.
   */
  noteOn(note, velocity, seed, p, j) {
    this.reset();
    this.note = note;
    this.velocity = velocity;
    this.active = true;
    this.env.fill(1);
    this.dropEnv = 1;
    this.click = 1;
    this.rng.seed(seed);
    const sr = this.sampleRate;
    this.norm = drumModes(at(p.material, j), at(p.edge, j), this.ratios, this.levels);
    const decay = Math.max(MIN_SEC, at(p.decay, j));
    const d = decay * sr;
    const tilt = 1 - Math.min(1, Math.max(0, at(p.ring, j)));
    for (let k = 0; k < DRUM_MODES; k++) this.gains[k] = Math.exp((-LN1000 * Math.pow(this.ratios[k], tilt)) / d);
    this.dropG = Math.exp(-1 / (DROP_SHARE * decay * sr));
    this.pitch = at(p.pitch, j);
    this.drop = at(p.drop, j);
    this.clickLevel = at(p.click, j);
    this.mix = Math.min(1, Math.max(0, at(p.noise, j)));
    const tone = at(p.noisetone, j);
    this.filter.setCutoff(tone, NOISE_RES);
    this.toneGain = noiseGain(tone, sr);
    const snap = Math.max(MIN_SEC, at(p.noiselength, j));
    this.tailG = Math.exp(-LN1000 / (snap * sr));
    this.burstG = Math.exp(-LN1000 / (Math.min(BURST_SEC, snap) * sr));
    const tail = Math.min(1, Math.max(0, at(p.noisetail, j)));
    this.slowLevel = TAIL_LEVEL * tail * tail;
    this.slowG = Math.exp(-LN1000 / (TAIL_LENGTH * snap * sr));
    this.drive = Math.min(1, Math.max(0, at(p.drive, j)));
    this.fm = DRUM_FM_DEPTH * Math.min(1, Math.max(0, at(p.fm, j)));
    this.fmRatio = at(p.fmratio, j);
    this.cutoff = at(p.cutoff, j);
    this.resonance = at(p.resonance, j);
    this.sweep = at(p.filtersweep, j);
    this.sweepG = Math.exp(-LN1000 / (Math.max(MIN_SEC, at(p.filterdecay, j)) * sr));
    this.sweepEnv = 1;
    this.filtered = !(this.cutoff >= DRUM_CUTOFF_TOP && this.sweep >= 0);
    if (this.filtered) this.tune(this.cutoff);
    // The highest mode sounding, for how far the FM's sidebands reach.
    this.topRatio = 0;
    for (let k = 0; k < DRUM_MODES; k++) if (this.levels[k] > 0 && this.ratios[k] > this.topRatio) this.topRatio = this.ratios[k];
    const gap = Math.min(1, Math.max(0, at(p.stutter, j))) * DRUM_GAP_SEC * sr;
    for (let b = 0; b < DRUM_BURSTS; b++) this.burstAt[b] = Math.round(b * gap);
    this.nextBurst = 0;
    this.tailAt = Math.round(DRUM_BURSTS * gap);
    this.tailOn = false;
  }

  /** Tunes the lowpass, with Resonance reaching nearly to oscillation (DRUM_LADDER_K). */
  tune(hz) {
    this.ladder.setCutoff(hz, 0);
    this.ladder.k = DRUM_LADDER_K * Math.min(1, Math.max(0, this.resonance));
  }

  /** Renders `count` samples of this voice and adds them into the output. */
  process(outL, outR, count, offset, s) {
    const sr = this.sampleRate;
    const p = s.values;
    const phase = this.phase;
    const env = this.env;
    const ratios = this.ratios;
    const levels = this.levels;
    const gains = this.gains;
    const bendMoving = s.bendArray !== null;
    let hz = midiToHz(this.note + this.pitch + s.bendAt(offset));
    const clickG = Math.exp(-LN1000 / (CLICK_SEC * sr));
    const velocity = this.velocity;
    const norm = this.norm;
    const mix = this.mix;
    const clickGain = CLICK_GAIN * velocity * this.clickLevel;

    for (let i = 0; i < count; i++) {
      const j = offset + i;
      if (bendMoving && i > 0) hz = midiToHz(this.note + this.pitch + s.bendAt(j));

      // The body: every mode at the lowest one's frequency times its ratio, raised by the drop.
      const semis = this.drop * this.dropEnv;
      this.dropEnv *= this.dropG;
      const f = (hz * (semis > 1e-6 ? Math.pow(2, semis / 12) : 1)) / sr;
      // The second sine's bend on every mode's phase, fading with the sweep's envelope.
      let bend = 0;
      if (this.fm > 0) {
        const index = this.fm * this.sweepEnv;
        // Carson's rule: the sidebands reach the index plus one times the FM's frequency past
        // the highest mode. Faded out as that nears the top of the band.
        const reach = f * (this.topRatio + (index + 1) * this.fmRatio);
        const fade = reach <= DRUM_FM_FULL ? 1 : (reach >= DRUM_FM_NONE ? 0 : (DRUM_FM_NONE - reach) / (DRUM_FM_NONE - DRUM_FM_FULL));
        bend = index * fade * Math.sin(DRUM_TWO_PI * this.fmPhase);
        this.fmPhase += f * this.fmRatio;
        if (this.fmPhase >= 1) this.fmPhase -= Math.floor(this.fmPhase);
      }
      let body = 0;
      for (let k = 0; k < DRUM_MODES; k++) {
        if (levels[k] > 0) {
          const inc = f * ratios[k];
          const bl = inc < BL_FULL ? 1 : (inc >= BL_NONE ? 0 : (BL_NONE - inc) / (BL_NONE - BL_FULL));
          if (bl > 0) body += levels[k] * env[k] * bl * Math.sin(DRUM_TWO_PI * phase[k] + bend);
          phase[k] += inc;
          if (phase[k] >= 1) phase[k] -= Math.floor(phase[k]);
        }
        env[k] *= gains[k];
      }

      // The noise: bursts as Stutter laid them out, then the tail, whichever is louder.
      const t = this.t;
      while (this.nextBurst < DRUM_BURSTS && t >= this.burstAt[this.nextBurst]) {
        this.burst = 1;
        this.nextBurst++;
      }
      if (!this.tailOn && t >= this.tailAt) {
        this.tail = 1;
        this.slow = 1;
        this.tailOn = true;
      }
      const w = this.rng.white();
      const stages = this.tail + this.slowLevel * this.slow;
      const level = this.burst > stages ? this.burst : stages;
      const noise = this.filter.next(w, 2) * this.toneGain * level;
      this.burst *= this.burstG;
      this.tail *= this.tailG;
      this.slow *= this.slowG;
      const click = (w - this.lastWhite) * this.click;
      this.lastWhite = w;
      this.click *= clickG;
      this.t = t + 1;

      let x = ((1 - mix) * norm * body + mix * noise + clickGain * click) * velocity;
      if (this.filtered) {
        if (this.sweep !== 0) this.tune(this.cutoff * Math.pow(2, (this.sweep * this.sweepEnv) / 12));
        x = this.ladder.next(x) * (1 + DRUM_RES_MAKEUP * this.ladder.k);
      }
      this.sweepEnv *= this.sweepG;
      const v = drive(x, this.drive) * at(p.level, j);
      outL[i] += v;
      outR[i] += v;
    }

    if (!Number.isFinite(this.filter.ic1 + this.filter.ic2 + phase[0] + env[0])) {
      this.reset();
      this.active = false;
      return;
    }
    const ls = this.ladder.s;
    const ringing = this.filtered && Math.abs(ls[0]) + Math.abs(ls[1]) + Math.abs(ls[2]) + Math.abs(ls[3]) >= SILENT;
    if (this.tailOn && env[0] < SILENT && this.tail < SILENT && this.slowLevel * this.slow < SILENT && this.burst < SILENT && this.click < SILENT && !ringing) {
      this.active = false;
    }
  }
}

class DrumSynth {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.voices = Array.from({ length: 16 }, () => new DrumVoice(sampleRate));
    this.voiceCount = 8;
    this.clock = 0;
    this.seed = 1;
    this.events = [];
    this.bend = 0;
    this.bendArray = null;
    this.state = {
      values: Object.fromEntries(DRUM.params.map((p) => [p.id, p.default])),
      bendArray: null,
      bendAt: (i) => (this.bendArray ? this.bendArray[i] : this.bend),
    };
  }

  /** The controls in real units: a number, or a block of values for one a signal is moving. */
  setParams(values) {
    const s = this.state;
    for (const p of DRUM.params) {
      const v = values[p.id];
      if (v === undefined) continue;
      if (typeof v === 'number' ? Number.isFinite(v) : v.length > 0) s.values[p.id] = v;
    }
    const count = at(s.values.voices, 0);
    if (Number.isFinite(count)) this.voiceCount = Math.max(1, Math.round(count));
    while (this.voices.length < this.voiceCount) this.voices.push(new DrumVoice(this.sampleRate));
  }

  /** The track's bend in semitones, which moves every body. */
  setBend(bend) {
    if (typeof bend === 'number') {
      this.bend = Number.isFinite(bend) ? bend : 0;
      this.bendArray = null;
    } else {
      this.bend = bend[0];
      this.bendArray = bend;
    }
    this.state.bendArray = this.bendArray;
  }

  queueNoteOn(note, velocity, offset = 0) {
    this.events.push({ at: Math.max(0, offset | 0), note, velocity });
  }

  /** A hit plays out: there is nothing for a note off to do. */
  queueNoteOff() {}

  /** Stop lets what is ringing ring out; only hits not yet started are dropped. */
  allNotesOff() {
    this.events.length = 0;
  }

  get activeVoices() {
    let n = 0;
    for (const v of this.voices) if (v.active) n++;
    return n;
  }

  /** A free voice, or the oldest. */
  allocate() {
    let oldest = null;
    for (let i = 0; i < this.voiceCount; i++) {
      const v = this.voices[i];
      if (!v.active) return v;
      if (!oldest || v.age < oldest.age) oldest = v;
    }
    return oldest ?? this.voices[0];
  }

  /** Starts a hit, struck with the controls at sample `j` of the block. */
  startNote(note, velocity, j) {
    const voice = this.allocate();
    voice.age = this.clock++;
    this.seed = (this.seed * 1664525 + 1013904223) >>> 0;
    voice.noteOn(note, velocity, this.seed, this.state.values, j);
  }

  /** Renders one block, split wherever a queued hit falls. */
  process(outL, outR, count) {
    const events = this.events;
    if (events.length > 1) events.sort((a, b) => a.at - b.at);
    let at0 = 0;
    let next = 0;
    while (at0 < count) {
      const first = next;
      while (next < events.length && events[next].at <= at0) next++;
      const until = next < events.length ? Math.min(count, events[next].at) : count;
      const n = until - at0;
      // Struck with the controls a sample in, where the piece has one (see the header).
      for (let e = first; e < next; e++) this.startNote(events[e].note, events[e].velocity, n > 1 ? at0 + 1 : at0);
      if (n > 0) {
        const l = at0 === 0 && n === outL.length ? outL : outL.subarray(at0, at0 + n);
        const r = at0 === 0 && n === outR.length ? outR : outR.subarray(at0, at0 + n);
        for (const v of this.voices) if (v.active) v.process(l, r, n, at0, this.state);
      }
      at0 = until;
    }
    if (next >= events.length) events.length = 0;
    else this.events = events.slice(next).map((e) => ({ ...e, at: Math.max(0, e.at - count) }));
  }
}

// ---- src/worklets/shared.mjs -------------------------------------
// What every poptart worklet needs from the descriptor it is built against.
//
// The parameter list an AudioWorkletProcessor declares and the parameter list the descriptor
// declares must be the same list, or a control exists on one side and not the other - which
// shows up as a knob that does nothing and no error anywhere. So it is generated from the
// descriptor rather than written twice.
//
// EVERY AUDIOPARAM IS A POSITION, 0..1. That is what `.param()` writes, what an LFO or an envelope
// sweeps, and what a patched audio signal adds to - one contract for every control on every
// device, the same as a plugin parameter. The DSP wants real units, so each worklet turns the
// positions it is handed into Hz, seconds, semitones and modes through the descriptor's own
// curve, per sample where a signal is moving the control and once where nothing is. That
// conversion is here, once, so a synth and an effect and a ported module all do it the same way.


/**
 * The processor's parameter descriptors, straight from the device's own.
 *
 * Every parameter becomes an AudioParam, k-rate ones included. Declaring the k-rate ones here
 * too rather than passing them over the message port means there is exactly one way a parameter
 * reaches the audio thread - and a mode that arrives a block later than the value it belongs
 * with is a bug nobody will find by reading.
 *
 * An instrument declares one more, the track's bend in semitones (TRACK_BEND_PARAM). It is not
 * a position and has no range.
 */
function parameterDescriptorsFor(descriptor) {
  const params = descriptor.params.map((p) => ({
    name: p.id,
    defaultValue: positionOfDefault(p),
    minValue: 0,
    // An open control's position runs past 1 for a value past the knob's reach (see defineParam).
    maxValue: p.open ? 3.4e38 : 1,
    automationRate: p.rate === 'a' ? 'a-rate' : 'k-rate',
  }));
  if (descriptor.kind === 'synth') params.push({ name: TRACK_BEND_PARAM, defaultValue: 0, automationRate: 'a-rate' });
  return params;
}

/**
 * The track's bend for this block, in semitones: a number while it is still, the block's own
 * array while something is moving it. The array is the AudioParam's, valid for this block only.
 *
 * The track's bend constant is always connected, and a connected AudioParam arrives a full block
 * long even when it is not moving - so a flat block is caught here and handed on as the number
 * it is, and a synth follows the pitch per sample only while a bend is actually moving.
 */
function bendOf(parameters) {
  const values = parameters[TRACK_BEND_PARAM];
  if (!values || values.length === 0) return 0;
  const first = values[0];
  for (let i = 1; i < values.length; i++) if (values[i] !== first) return values;
  return first;
}

/** Where a parameter's default sits, as the position its AudioParam starts at. */
function positionOfDefault(p) {
  if (p.curve === 'exp') return Math.log(p.default / p.min) / Math.log(p.max / p.min);
  if (p.curve === 'pow') return Math.pow((p.default - p.min) / (p.max - p.min), 1 / p.curveExp);
  if (p.curve === 'sym') {
    const u = (p.default - (p.min + p.max) / 2) / ((p.max - p.min) / 2);
    return (1 + Math.sign(u) * Math.pow(Math.abs(u), 1 / p.curveExp)) / 2;
  }
  return (p.default - p.min) / (p.max - p.min);
}

/**
 * Reads a block's worth of one parameter as a plain number.
 *
 * An AudioParam that is not being automated arrives as a single-element array, which is the
 * common case for a control nobody is moving; one that is arrives with a value per sample. A
 * device that wants the whole block keeps the array, and one that only needs a block-rate value
 * takes the first element - this is for the second kind, which is every ported module.
 */
function blockValue(values, fallback = 0) {
  if (!values || values.length === 0) return fallback;
  return values[0];
}

/**
 * Turns the positions a worklet is handed into the real values its DSP reads, in place.
 *
 * `out` is a plain object the caller keeps for the life of the processor, and `scratch` a map of
 * per-parameter Float32Arrays it also keeps: a moving control is converted into its own scratch
 * array and a still one into a number, so the hot path allocates nothing. The DSP reads the
 * result with `at()` from dsp/control.mjs, which takes either shape.
 */
function realParams(descriptor, parameters, out, scratch) {
  for (const p of descriptor.params) {
    const values = parameters[p.id];
    if (!values || values.length === 0) { out[p.id] = p.default; continue; }
    if (values.length === 1) { out[p.id] = denormalize(p, values[0]); continue; }
    let buf = scratch[p.id];
    if (!buf || buf.length < values.length) buf = scratch[p.id] = new Float32Array(values.length);
    for (let i = 0; i < values.length; i++) buf[i] = denormalize(p, values[i]);
    out[p.id] = buf;
  }
  return out;
}

/** The positions a processor last read, as `{ id: position }` - what it reports to a panel. */
function lastPositions(descriptor, parameters, out) {
  for (const p of descriptor.params) {
    const values = parameters[p.id];
    if (values && values.length) out[p.id] = values[values.length - 1];
  }
  return out;
}

/**
 * Whether a message tells a processor to shut down.
 *
 * A processor lives for exactly as long as its `process` returns true, and the browser keeps it
 * alive on that answer alone - being disconnected from everything does not end it. So a device
 * that has been replaced or removed has to be TOLD, and the alternative of guessing from a
 * silent input is worse than it looks: an effect whose track is resting between notes sees the
 * same empty input as one that has been unplugged, and a processor that returns false is gone
 * for good. Guessing wrong in that direction is a chain that goes permanently silent partway
 * through a set, which is the one failure this codebase is least willing to ship.
 */
function isDispose(message) {
  return message?.kind === 'dispose';
}

/**
 * How often a watched processor reports its parameters back, in blocks. Around thirty times a
 * second at the usual block size: enough for a picture to follow a modulator, cheap enough to
 * leave on for as long as a device window is open.
 */
const REPORT_EVERY_BLOCKS = 5;

/**
 * The part of a processor's port protocol every poptart worklet shares: a `watch` message turns
 * reporting on and off, and while it is on the processor posts the positions it last read, so
 * a panel can draw a control something else is driving where it actually is rather than where
 * it was set.
 */
class Reporter {
  constructor(port, descriptor) {
    this.port = port;
    this.descriptor = descriptor;
    this.on = false;
    this.blocks = 0;
    this.values = {};
  }

  /** Whether a message was a watch toggle, and applies it if so. */
  receive(message) {
    if (message?.kind !== 'watch') return false;
    this.on = !!message.on;
    this.blocks = 0;
    return true;
  }

  /**
   * Called once per rendered block with the parameters it was handed.
   *
   * `report` is whatever else a device has to say about what it is doing right now - a
   * granulator's grains, a compressor's last second of levels. It rides the same message because
   * it is the same question the panel is asking: what is this device doing, as opposed to what
   * was it set to, and a second channel for it would only be a second thing to turn on and off.
   * Given as a function, so a device that copies a history out to answer does so only on the
   * blocks that post, and not on the four in between.
   */
  tick(parameters, report = null) {
    if (!this.on) return;
    if (++this.blocks < REPORT_EVERY_BLOCKS) return;
    this.blocks = 0;
    const said = typeof report === 'function' ? report() : report;
    this.port.postMessage({ kind: 'values', values: lastPositions(this.descriptor, parameters, this.values), report: said ?? null });
  }
}

/**
 * Turns an absolute time on the context's clock into a sample offset inside the block about to
 * be rendered.
 *
 * `currentFrame` counts samples since the context started, so this is exact rather than being
 * derived from a float second count that has already lost precision by the time a set has been
 * running for an hour. An event in the past lands at the start of the block - late is better
 * than dropped - and one at or past the end of the block comes back as is, which the caller
 * reads as "keep it for a later block".
 */
function offsetInBlock(time, currentFrame, sampleRate, blockSize) {
  if (!Number.isFinite(time)) return 0;
  const frame = Math.round(time * sampleRate) - currentFrame;
  if (frame <= 0) return 0;
  return frame;
}

// ---- src/worklets/synths.worklet.js ------------------------------
// The synths poptart wrote, as AudioWorkletProcessors.
//
// A thin wrapper on purpose: everything that makes a sound lives in src/dsp and src/devices and
// is unit-tested in plain node, and what is left here is the part that can only be tested in a
// browser - the parameter plumbing and the note timing. Keeping that part small is the whole
// strategy, and it is the same for every synth, so one class serves them all and each registers
// its own name around it.
//
// The parameters arrive as positions and go to the synth as real units - a one-sample array for
// a control that is still, a block-long one for a control a signal is moving, converted through
// the descriptor's own curve either way (see shared.mjs). The synth reads the moving ones per
// sample, which is what makes an lfo() on a position a sweep rather than a staircase.


// The tables are built here, as the script loads, rather than in the first processor's
// constructor: a hundred milliseconds of harmonic sums is an audible dropout on the rendering
// thread once a context is running, and nothing at all before it is.
sharedBuiltInTables();

class SynthProcessor extends AudioWorkletProcessor {
  constructor(options, descriptor, synth) {
    super(options);
    this.descriptor = descriptor;
    this.synth = synth;
    // Notes arrive with an absolute time on the context's clock and are held here until the
    // block they belong in - which is what stops a part walking against the grid by up to a
    // block, nearly three milliseconds, every time it plays.
    this.pending = [];
    this.alive = true;
    this.real = {};
    this.scratch = {};
    this.reporter = new Reporter(this.port, descriptor);
    if (typeof synth.setTempo === 'function') synth.setTempo(options?.processorOptions?.bpm ?? 120, options?.processorOptions?.anchorSec ?? 0);
    this.port.onmessage = (event) => this.receive(event.data);
  }

  receive(message) {
    if (!message) return;
    if (message.kind === 'noteOn' || message.kind === 'noteOff') {
      this.pending.push(message);
      return;
    }
    if (message.kind === 'allNotesOff') {
      this.pending.length = 0;
      this.synth.allNotesOff();
      return;
    }
    if (isDispose(message)) {
      this.pending.length = 0;
      this.alive = false;
      return;
    }
    if (this.reporter.receive(message)) return;
    if (message.kind === 'tempo' && typeof this.synth.setTempo === 'function') { this.synth.setTempo(message.bpm, message.anchorSec); return; }
    if (message.kind === 'sample' && typeof this.synth.loadSample === 'function') {
      this.synth.loadSample(message.param, message.index, message);
      return;
    }
    // A curve somebody drew, already sampled into a table by the engine - see _loadShapeParam.
    if (message.kind === 'shape' && typeof this.synth.loadShape === 'function') {
      this.synth.loadShape(message.param, message.index, message.table);
    }
  }

  /** Moves every note edge that lands in this block into the synth, with its sample offset. */
  drain(blockSize) {
    if (this.pending.length === 0) return;
    const keep = [];
    for (const event of this.pending) {
      const offset = offsetInBlock(event.time, currentFrame, sampleRate, blockSize);
      if (offset >= blockSize) { keep.push(event); continue; }
      if (event.kind === 'noteOn') this.synth.queueNoteOn(event.note, event.velocity, offset);
      else this.synth.queueNoteOff(event.note, offset);
    }
    this.pending = keep;
  }

  process(inputs, outputs, parameters) {
    if (!this.alive) return false;
    const out = outputs[0];
    if (!out || out.length === 0) return true;
    const blockSize = out[0].length;

    this.synth.setParams(realParams(this.descriptor, parameters, this.real, this.scratch));
    // The track's bend, which the track keeps connected: per sample while it moves.
    this.synth.setBend(bendOf(parameters));
    this.drain(blockSize);

    out[0].fill(0);
    if (out[1]) out[1].fill(0);
    this.synth.process(out[0], out[1] ?? out[0], blockSize);
    this.reporter.tick(parameters, () => this.synth.report?.());

    // A synth with nothing sounding and nothing queued still has to stay alive: the next note is
    // a message away, and a processor that returned false would have been torn down by then.
    // Which is why the engine has to say when a device is finished with - see the dispose
    // message above, and _buildDevice's dispose on the other end of it.
    return true;
  }
}

const SYNTHS = [
  [WAVETABLE, () => new WavetableSynth(sampleRate)],
  [FMSYNTH, () => new FmSynth(sampleRate)],
  [GRANULAR, () => new GranularSynth(sampleRate)],
  [NOISE, () => new NoiseSynth(sampleRate)],
  [FORMANT, () => new FormantSynth(sampleRate)],
  [ADDITIVE, () => new AdditiveSynth(sampleRate)],
  [ANALOG, () => new AnalogSynth(sampleRate)],
  [KICK, () => new KickSynth(sampleRate)],
  [HAT, () => new HatSynth(sampleRate)],
  [DRUM, () => new DrumSynth(sampleRate)],
];

for (const [descriptor, make] of SYNTHS) {
  registerProcessor(descriptor.processor, class extends SynthProcessor {
    static get parameterDescriptors() { return parameterDescriptorsFor(descriptor); }
    constructor(options) { super(options, descriptor, make()); }
  });
}
